INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(73139, 2386, 2251, '<td valign="top">nothing drastic</td>', 'nothing drastic', '2002-06-17 04:22:00.000000', NULL, 1),
(73140, 2386, 1041, '<td valign="top">It''s a very visible shadow, you''ve placed the fountain well, it''s cool that the shadow falls on the dandylion ... but, still, the photo doesn''t really hold my interest for long.  Sorry.</td>', 'It''s a very visible shadow, you''ve placed the fountain well, it''s cool that the shadow falls on the dandylion ... but, still, the photo doesn''t really hold my interest for long.  Sorry.', '2002-06-17 16:14:00.000000', NULL, 1),
(73141, 2386, 2172, '<td valign="top">Image quality not bad</td>', 'Image quality not bad', '2002-06-17 16:20:00.000000', NULL, 1),
(73142, 2386, 772, '<td valign="top">This is a neat shadow... I think I may like it more from a slightly lower camera angle maybe..</td>', 'This is a neat shadow... I think I may like it more from a slightly lower camera angle maybe..', '2002-06-18 11:40:00.000000', NULL, 1),
(73143, 2386, 1005, '<td valign="top">I''d comment, but you wouldn''t like it.</td>', 'I''d comment, but you wouldn''t like it.', '2002-06-18 14:07:00.000000', NULL, 1),
(73144, 2386, 1759, '<td valign="top">Good exposure, focus, and composition though not the most visually pleasing subject.</td>', 'Good exposure, focus, and composition though not the most visually pleasing subject.', '2002-06-18 14:21:00.000000', NULL, 1),
(73145, 2386, 1175, '<td valign="top">Yeah that''s a shadow alright.  But what''s exciting about this picture?  You placed the fountain in a good place.</td>', 'Yeah that''s a shadow alright.  But what''s exciting about this picture?  You placed the fountain in a good place.', '2002-06-18 15:43:00.000000', NULL, 1),
(73146, 2386, 1054, '<td valign="top">That''s a cool-looking shadow.</td>', 'That''s a cool-looking shadow.', '2002-06-18 17:41:00.000000', NULL, 1),
(73147, 2386, 2312, '<td valign="top">This makes me wonder if the weed is trying to hide out to survive.</td>', 'This makes me wonder if the weed is trying to hide out to survive.', '2002-06-19 15:46:00.000000', NULL, 1),
(73148, 2386, 205, '<td valign="top">too much negative space on the left</td>', 'too much negative space on the left', '2002-06-20 09:12:00.000000', NULL, 1),
(73149, 2386, 2263, '<td valign="top">?</td>', '?', '2002-06-20 21:42:00.000000', NULL, 1),
(73150, 2386, 1061, '<td valign="top">Funny how that weed can grow in a place that never gets any sun...</td>', 'Funny how that weed can grow in a place that never gets any sun...', '2002-06-23 04:41:00.000000', NULL, 1),
(73151, 2386, 1, '<td valign="top">The plants are distracting, I think a little uprooting was in order before you took this shot.  Sometimes you gotta get down and dirty.</td>', 'The plants are distracting, I think a little uprooting was in order before you took this shot.  Sometimes you gotta get down and dirty.', '2002-06-23 17:24:00.000000', NULL, 1),
(73152, 2388, 1054, '<td valign="top">The edge at the right is distracting and baby''s head is cut off at the very top.. This would have been more effective in a portrait orientation.</td>', 'The edge at the right is distracting and baby''s head is cut off at the very top.. This would have been more effective in a portrait orientation.', '2002-06-17 02:07:00.000000', NULL, 1),
(73153, 2388, 2251, '<td valign="top">kill all babies</td>', 'kill all babies', '2002-06-17 04:34:00.000000', NULL, 1),
(73154, 2388, 1175, '<td valign="top">DAMN THOSE ARE BIG CHEEKS!!! I thought using that morphing tool was against the rules.</td>', 'DAMN THOSE ARE BIG CHEEKS!!! I thought using that morphing tool was against the rules.', '2002-06-17 14:25:00.000000', NULL, 1),
(73155, 2388, 2261, '<td valign="top">lovely snap!</td>', 'lovely snap!', '2002-06-17 15:37:00.000000', NULL, 1),
(73156, 2388, 1041, '<td valign="top">Cuuute baby.  However, couple of questions/comments.  Why rotate the photo?  It looks very awkward that way.  Also, yes, there''s some shadow on babe''s face, but it''s very much not the focus of the photo.  Sorry.  Just my opinion.</td>', 'Cuuute baby.  However, couple of questions/comments.  Why rotate the photo?  It looks very awkward that way.  Also, yes, there''s some shadow on babe''s face, but it''s very much not the focus of the photo.  Sorry.  Just my opinion.', '2002-06-17 16:01:00.000000', NULL, 1),
(73157, 2388, 772, '<td valign="top">I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...</td>', 'I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...', '2002-06-17 16:46:00.000000', NULL, 1),
(73158, 2388, 203, '<td valign="top">Is this your best use of shadow?  Or a nice faimly snap shot keepsake?</td>', 'Is this your best use of shadow?  Or a nice faimly snap shot keepsake?', '2002-06-17 19:09:00.000000', NULL, 1),
(73159, 2388, 1759, '<td valign="top">A nice soft blanket to the right would hide the distractive background.</td>', 'A nice soft blanket to the right would hide the distractive background.', '2002-06-17 21:22:00.000000', NULL, 1),
(73160, 2388, 1, '<td valign="top">The shadow doesn''t work to the childs benefit...try re-positioning.</td>', 'The shadow doesn''t work to the childs benefit...try re-positioning.', '2002-06-18 09:11:00.000000', NULL, 1),
(73161, 2388, 806, '<td valign="top">I''m getting dizzy just looking at this picture. my whole equilibrium is off from it. A baby picture should illustrate the sweet innocence of a child. This does not do the baby justice.</td>', 'I''m getting dizzy just looking at this picture. my whole equilibrium is off from it. A baby picture should illustrate the sweet innocence of a child. This does not do the baby justice.', '2002-06-18 16:32:00.000000', NULL, 1),
(73162, 2388, 1569, '<td valign="top">Horizontal babies should remain horizontal.</td>', 'Horizontal babies should remain horizontal.', '2002-06-18 20:05:00.000000', NULL, 1),
(73163, 2388, 1856, '<td valign="top">cute baby...looks a little annoyed with the photographer for ruining her nap!</td>', 'cute baby...looks a little annoyed with the photographer for ruining her nap!', '2002-06-18 21:46:00.000000', NULL, 1),
(73164, 2388, 2247, '<td valign="top">Cute and funny.  Makes me chuckle in amusement.</td>', 'Cute and funny.  Makes me chuckle in amusement.', '2002-06-18 22:46:00.000000', NULL, 1),
(73165, 2388, 2217, '<td valign="top">Cute baby.  Perhaps there should be more contrast.</td>', 'Cute baby.  Perhaps there should be more contrast.', '2002-06-19 01:39:00.000000', NULL, 1),
(73166, 2393, 2111, '<td valign="top">Thats not a shadow its the moon blocking the Sun</td>', 'Thats not a shadow its the moon blocking the Sun', '2002-06-17 01:22:00.000000', NULL, 1),
(73167, 2393, 1054, '<td valign="top">Nice capture of the eclipse.</td>', 'Nice capture of the eclipse.', '2002-06-17 01:25:00.000000', NULL, 1),
(73168, 2393, 593, '<td valign="top">Nice job</td>', 'Nice job', '2002-06-17 02:33:00.000000', NULL, 1),
(73169, 2393, 1856, '<td valign="top">I don''t think this represents the challenge very well.  I see the silohuette of the cloud on the sun.  I would have scored this higher had the silouette been more interesting.</td>', 'I don''t think this represents the challenge very well.  I see the silohuette of the cloud on the sun.  I would have scored this higher had the silouette been more interesting.', '2002-06-17 10:49:00.000000', NULL, 1),
(73170, 2393, 1944, '<td valign="top">Nice picture. I forgot about it until too late:(</td>', 'Nice picture. I forgot about it until too late:(', '2002-06-17 14:25:00.000000', NULL, 1),
(73171, 2393, 570, '<td valign="top">is your definition of a shadow "one thing covering another thing" ?</td>', 'is your definition of a shadow "one thing covering another thing" ?', '2002-06-17 14:37:00.000000', NULL, 1),
(73172, 2393, 327, '<td valign="top">Loveyly color..wow! nice job.</td>', 'Loveyly color..wow! nice job.', '2002-06-17 15:25:00.000000', NULL, 1),
(73173, 2393, 1175, '<td valign="top">ok so this isn''t the greatest photo in the world but it is a great shot of a shadow.</td>', 'ok so this isn''t the greatest photo in the world but it is a great shot of a shadow.', '2002-06-17 17:50:00.000000', NULL, 1),
(73174, 2393, 772, '<td valign="top">Cool view?  Wassamatta?  couldn''t you get close enuff to fill the whole frame with the sun?  All you need is a 1,000,000,000mm zoom lens.. :)  (just kidding)  you have a very unique entry this week... great shot!</td>', 'Cool view?  Wassamatta?  couldn''t you get close enuff to fill the whole frame with the sun?  All you need is a 1,000,000,000mm zoom lens.. :)  (just kidding)  you have a very unique entry this week... great shot!', '2002-06-17 18:17:00.000000', NULL, 1),
(73175, 2393, 806, '<td valign="top">oh... you are sneaky! good for you!</td>', 'oh... you are sneaky! good for you!', '2002-06-17 19:00:00.000000', NULL, 1),
(73176, 2393, 1759, '<td valign="top">Nice color and perfect timing to get a good position. Another 4x magnification would be nice. Did you try cropping this down to see how it looked?</td>', 'Nice color and perfect timing to get a good position. Another 4x magnification would be nice. Did you try cropping this down to see how it looked?', '2002-06-17 21:25:00.000000', NULL, 1),
(73177, 2393, 671, '<td valign="top">I can''t wait to find out how you took it.  I would have framed it the other way, though, for greater impact.</td>', 'I can''t wait to find out how you took it.  I would have framed it the other way, though, for greater impact.', '2002-06-18 00:17:00.000000', NULL, 1),
(73178, 2393, 1599, '<td valign="top">The Ultimate Shadow......Awesome....Where was this taken.  Nice shot.  Do you know how to keep the lens open and get a picture of all the stars at nice.  I heard you must be in a dark dark place.  The camera needs to be steady, I think this is a great shot, and you probably know what I mean, b/c I can not do it.</td>', 'The Ultimate Shadow......Awesome....Where was this taken.  Nice shot.  Do you know how to keep the lens open and get a picture of all the stars at nice.  I heard you must be in a dark dark place.  The camera needs to be steady, I think this is a great shot, and you probably know what I mean, b/c I can not do it.', '2002-06-18 01:04:00.000000', NULL, 1),
(73179, 2393, 2216, '<td valign="top">gorgeous</td>', 'gorgeous', '2002-06-18 01:47:00.000000', NULL, 1),
(73180, 2393, 1908, '<td valign="top">lovely light</td>', 'lovely light', '2002-06-18 10:16:00.000000', NULL, 1),
(73181, 2393, 1005, '<td valign="top">Wow, eclipse, it''s not just a gum!  Like the pinks, really nice.  The flare beneath the sun is distracting, but really......Very nice.<br/>Photo 9 Creativity 10 Shadows 9 total 9</td>', 'Wow, eclipse, it''s not just a gum!  Like the pinks, really nice.  The flare beneath the sun is distracting, but really......Very nice.Photo 9 Creativity 10 Shadows 9 total 9', '2002-06-18 20:17:00.000000', NULL, 1),
(73182, 2393, 1031, '<td valign="top">Mine didn''t come out so well. Love for you to share the "how I did this" when the challenge is over.</td>', 'Mine didn''t come out so well. Love for you to share the "how I did this" when the challenge is over.', '2002-06-19 03:24:00.000000', NULL, 1),
(73183, 2393, 2188, '<td valign="top">Bravo!</td>', 'Bravo!', '2002-06-19 10:02:00.000000', NULL, 1),
(73184, 2393, 1485, '<td valign="top">I see that u are trying to use the eclipse as the shadow.  IT is sooooooooooo far away, it''s almost trivial in this image.</td>', 'I see that u are trying to use the eclipse as the shadow.  IT is sooooooooooo far away, it''s almost trivial in this image.', '2002-06-19 10:29:00.000000', NULL, 1),
(73185, 2393, 1330, '<td valign="top">I went out and set up to do this shot only to have heavy cloud cover move in. Thanks for this one. Love the reds.<br/>D</td>', 'I went out and set up to do this shot only to have heavy cloud cover move in. Thanks for this one. Love the reds.D', '2002-06-20 10:14:00.000000', NULL, 1),
(73186, 2393, 2125, '<td valign="top">nice! good job capturing the color and the foreground could cut the power lines but that is hard</td>', 'nice! good job capturing the color and the foreground could cut the power lines but that is hard', '2002-06-20 14:06:00.000000', NULL, 1),
(73187, 2393, 2263, '<td valign="top">Awesome.  How did you get this to turn out? I tried to take some pictures of the partial eclipse, they didn''t work.</td>', 'Awesome.  How did you get this to turn out? I tried to take some pictures of the partial eclipse, they didn''t work.', '2002-06-20 21:41:00.000000', NULL, 1),
(73188, 2393, 1, '<td valign="top">I don''t consider the blocking of light a shadow... a shadow is the result of light blocking, your subject here is the sun... not of a shadow.</td>', 'I don''t consider the blocking of light a shadow... a shadow is the result of light blocking, your subject here is the sun... not of a shadow.', '2002-06-22 12:43:00.000000', NULL, 1),
(73189, 2393, 749, '<td valign="top">Very fortuitous timing, having a partial eclipse the same week as the shadows challenge :o) Just a pity the shot wasn''t cropped in closer, as there''s too much dead space for my liking.</td>', 'Very fortuitous timing, having a partial eclipse the same week as the shadows challenge :o) Just a pity the shot wasn''t cropped in closer, as there''s too much dead space for my liking.', '2002-06-22 15:53:00.000000', NULL, 1),
(73190, 2393, 2079, '<td valign="top">I am glad to see this entry, "the ultimate shadow" I was watching this from California. I had my camera in my hand and the cloud cover ruined the oppertunity. I hope everyone gives you a bonus point for difficulty. This is a rare occurance.</td>', 'I am glad to see this entry, "the ultimate shadow" I was watching this from California. I had my camera in my hand and the cloud cover ruined the oppertunity. I hope everyone gives you a bonus point for difficulty. This is a rare occurance.', '2002-06-23 02:04:00.000000', NULL, 1),
(73191, 2393, 661, '<td valign="top">Nice catch of the eclipse!</td>', 'Nice catch of the eclipse!', '2002-06-24 00:27:00.000000', NULL, 1),
(73192, 2395, 1856, '<td valign="top">Nice shades.</td>', 'Nice shades.', '2002-06-17 11:02:00.000000', NULL, 1),
(73193, 2395, 1897, '<td valign="top">good composition</td>', 'good composition', '2002-06-17 14:09:00.000000', NULL, 1),
(73194, 2395, 1944, '<td valign="top">Photos like this work best when they''re brutally sharp. This one has a way to go.</td>', 'Photos like this work best when they''re brutally sharp. This one has a way to go.', '2002-06-17 15:32:00.000000', NULL, 1),
(73195, 2395, 772, '<td valign="top">This is a nice composition!  The shadows and curves here are really appealing, as is the lighting and the contrasts... Great eye!  Excellent work...</td>', 'This is a nice composition!  The shadows and curves here are really appealing, as is the lighting and the contrasts... Great eye!  Excellent work...', '2002-06-17 16:25:00.000000', NULL, 1),
(73196, 2395, 1313, '<td valign="top">Nice crisp shadows and pic but uninteresting subject and no color has plusses and minuses.</td>', 'Nice crisp shadows and pic but uninteresting subject and no color has plusses and minuses.', '2002-06-17 19:16:00.000000', NULL, 1),
(73197, 2395, 2153, '<td valign="top">Very stark. I love it.</td>', 'Very stark. I love it.', '2002-06-17 23:32:00.000000', NULL, 1),
(73198, 2395, 1599, '<td valign="top">ok, and not ok</td>', 'ok, and not ok', '2002-06-18 01:24:00.000000', NULL, 1),
(73199, 2395, 1792, '<td valign="top">Good composition.  Good shadow theme.</td>', 'Good composition.  Good shadow theme.', '2002-06-18 01:37:00.000000', NULL, 1),
(73200, 2395, 1, '<td valign="top">Black and white works well for showing the contrast between your subject and your shadow.  Nicely shot.</td>', 'Black and white works well for showing the contrast between your subject and your shadow.  Nicely shot.', '2002-06-18 09:02:00.000000', NULL, 1),
(73201, 2395, 1175, '<td valign="top">This is very cool.  Abstract.  Industrial.  I like it alot.</td>', 'This is very cool.  Abstract.  Industrial.  I like it alot.', '2002-06-18 16:50:00.000000', NULL, 1),
(73202, 2395, 1054, '<td valign="top">This image needs to be rotated slightly counterclockwise.</td>', 'This image needs to be rotated slightly counterclockwise.', '2002-06-18 17:08:00.000000', NULL, 1),
(73203, 2395, 1005, '<td valign="top">Very good exposure/focus/ etc.  Technically this is a fine photo.  Artistically, maybe it needs explaining, but doesn''t do much for me, sorry.<br/>Photo 8 Creativity 5 Shadows 7 total 7</td>', 'Very good exposure/focus/ etc.  Technically this is a fine photo.  Artistically, maybe it needs explaining, but doesn''t do much for me, sorry.Photo 8 Creativity 5 Shadows 7 total 7', '2002-06-19 19:53:00.000000', NULL, 1),
(73204, 2395, 1037, '<td valign="top">Great (tinted?) black and white and nice textures. The structures here are interesting in an abstract way.</td>', 'Great (tinted?) black and white and nice textures. The structures here are interesting in an abstract way.', '2002-06-20 05:14:00.000000', NULL, 1),
(73205, 2395, 641, '<td valign="top">Crop out the right side to get that other black pole out and it would be perfect.</td>', 'Crop out the right side to get that other black pole out and it would be perfect.', '2002-06-21 16:01:00.000000', NULL, 1),
(73206, 2395, 772, '<td valign="top">This is a GREAT photo.. you got ripped on the score.. this should have been way on up there in my opinion... one of my favorites this week for sure...  To me, this shot has great artistic value... great work!</td>', 'This is a GREAT photo.. you got ripped on the score.. this should have been way on up there in my opinion... one of my favorites this week for sure...  To me, this shot has great artistic value... great work!', '2002-06-24 01:46:00.000000', NULL, 0),
(73207, 2395, 1175, '<td valign="top">This was one of my tens.  You really got ripped off on this.  Makes me think we just have a bunch of monkey''s voting on this site.</td>', 'This was one of my tens.  You really got ripped off on this.  Makes me think we just have a bunch of monkey''s voting on this site.', '2002-06-24 11:17:00.000000', NULL, 0),
(73208, 2396, 1944, '<td valign="top">Nice design.</td>', 'Nice design.', '2002-06-17 02:34:00.000000', NULL, 1),
(73209, 2396, 2251, '<td valign="top">it''s not just about the shadows</td>', 'it''s not just about the shadows', '2002-06-17 04:24:00.000000', NULL, 1),
(73210, 2396, 570, '<td valign="top">ok</td>', 'ok', '2002-06-17 14:38:00.000000', NULL, 1),
(73211, 2396, 327, '<td valign="top">Nice shadows~</td>', 'Nice shadows~', '2002-06-17 16:45:00.000000', NULL, 1),
(73212, 2396, 1599, '<td valign="top">this is ok</td>', 'this is ok', '2002-06-18 01:42:00.000000', NULL, 1),
(73213, 2396, 1054, '<td valign="top">Nice shadows and angles.</td>', 'Nice shadows and angles.', '2002-06-18 15:38:00.000000', NULL, 1),
(73214, 2396, 1783, '<td valign="top">Nice and simple, but it would be nice to see the object creating the shadow as well.</td>', 'Nice and simple, but it would be nice to see the object creating the shadow as well.', '2002-06-19 09:24:00.000000', NULL, 1),
(73215, 2396, 2301, '<td valign="top">A good picture...</td>', 'A good picture...', '2002-06-20 15:48:00.000000', NULL, 1),
(73216, 2396, 772, '<td valign="top">I love the patterns in your shadows here... I''m a fan of diagonals as well... good shot! - jmsetzler</td>', 'I love the patterns in your shadows here... I''m a fan of diagonals as well... good shot! - jmsetzler', '2002-06-20 17:58:00.000000', NULL, 1),
(73217, 2396, 1175, '<td valign="top">I like the patterns.  I just not really drawn into this pic.</td>', 'I like the patterns.  I just not really drawn into this pic.', '2002-06-21 15:00:00.000000', NULL, 1),
(73218, 2396, 715, '<td valign="top">Very well framed.</td>', 'Very well framed.', '2002-06-23 16:12:00.000000', NULL, 1),
(73219, 2396, 1, '<td valign="top">I think showing more of the shadow, and less sidewalk space (top right) would''ve worked out even better.</td>', 'I think showing more of the shadow, and less sidewalk space (top right) would''ve worked out even better.', '2002-06-23 19:06:00.000000', NULL, 1),
(73220, 2396, 637, '<td valign="top">I like this image cuz we can see the shadow but not the original subject.</td>', 'I like this image cuz we can see the shadow but not the original subject.', '2002-06-24 00:14:00.000000', NULL, 1),
(73221, 2397, 2251, '<td valign="top">kill all babies</td>', 'kill all babies', '2002-06-17 04:37:00.000000', NULL, 1),
(73222, 2397, 2172, '<td valign="top">Cute picture, yet the quality of the image is not quite right</td>', 'Cute picture, yet the quality of the image is not quite right', '2002-06-17 15:46:00.000000', NULL, 1),
(73223, 2397, 1759, '<td valign="top">Shadows on a newborn, cute baby!  I would like to see stronger more defined shadows. What might have made this better (easier said than done) is casting a strong shadow from a direct light source using the baby''s mobile or some such thing. Also, shift baby off center to get rid of the distraction from the left side.</td>', 'Shadows on a newborn, cute baby!  I would like to see stronger more defined shadows. What might have made this better (easier said than done) is casting a strong shadow from a direct light source using the baby''s mobile or some such thing. Also, shift baby off center to get rid of the distraction from the left side.', '2002-06-17 16:06:00.000000', NULL, 1),
(73224, 2397, 1944, '<td valign="top">Too many compression artifacts.</td>', 'Too many compression artifacts.', '2002-06-17 17:28:00.000000', NULL, 1),
(73225, 2397, 1041, '<td valign="top">There''s something so peaceful about sleeping newborns, isn''t it?  Have you considered taking this photo from a different angle, if possible, maybe more face on so that the baby''s face is visible?  Also, I would try and save the image with a larger file size, there''s a lot of pixelation visible that shouldn''t be necessary.  Last but not least, while there''s shadow in the photo, it''s totally not the focus, sorry.</td>', 'There''s something so peaceful about sleeping newborns, isn''t it?  Have you considered taking this photo from a different angle, if possible, maybe more face on so that the baby''s face is visible?  Also, I would try and save the image with a larger file size, there''s a lot of pixelation visible that shouldn''t be necessary.  Last but not least, while there''s shadow in the photo, it''s totally not the focus, sorry.', '2002-06-17 17:34:00.000000', NULL, 1),
(73226, 2397, 1005, '<td valign="top">Sorry to ask, but lower end camera?  Appears a bit smudgy, could be from over sharpening, also. Nice shadow lattice (spots of sun and shade).<br/>Photo 7 Creativity 6 Shadows 6 total 6</td>', 'Sorry to ask, but lower end camera?  Appears a bit smudgy, could be from over sharpening, also. Nice shadow lattice (spots of sun and shade).Photo 7 Creativity 6 Shadows 6 total 6', '2002-06-17 18:02:00.000000', NULL, 1),
(73227, 2397, 203, '<td valign="top">Is this your best use of shadow?  Or a wonderful family keep sake snapshot?</td>', 'Is this your best use of shadow?  Or a wonderful family keep sake snapshot?', '2002-06-17 19:07:00.000000', NULL, 1),
(73228, 2397, 1856, '<td valign="top">beautiful baby...not so beautiful photo to enter a contest.  All of those different blankets and textures together are ugly...I can barely see the shadows fro the loud clashing patterns.  Did I mention the baby''s beautiful?</td>', 'beautiful baby...not so beautiful photo to enter a contest.  All of those different blankets and textures together are ugly...I can barely see the shadows fro the loud clashing patterns.  Did I mention the baby''s beautiful?', '2002-06-17 22:47:00.000000', NULL, 1),
(73229, 2397, 1882, '<td valign="top">great snapshot</td>', 'great snapshot', '2002-06-18 10:36:00.000000', NULL, 1),
(73230, 2397, 806, '<td valign="top">Infant pictures should show the beauty and innocence of your baby. This does a disservice to the child. There are so many other ways to have taken this baby''s picture.</td>', 'Infant pictures should show the beauty and innocence of your baby. This does a disservice to the child. There are so many other ways to have taken this baby''s picture.', '2002-06-18 16:28:00.000000', NULL, 1),
(73231, 2397, 1054, '<td valign="top">The composition on this shot could be a lot better.  The items on the floor are a distraction.  I''m not sure I see the point to the odd angle, either.</td>', 'The composition on this shot could be a lot better.  The items on the floor are a distraction.  I''m not sure I see the point to the odd angle, either.', '2002-06-18 17:28:00.000000', NULL, 1),
(73232, 2397, 1569, '<td valign="top">Turn this one 90 degrees counter clockwise. The little one looks suspended in the air.</td>', 'Turn this one 90 degrees counter clockwise. The little one looks suspended in the air.', '2002-06-18 20:39:00.000000', NULL, 1),
(73233, 2397, 527, '<td valign="top">I would have preferred to see this with longer shadows so they are more pronounced.</td>', 'I would have preferred to see this with longer shadows so they are more pronounced.', '2002-06-19 00:53:00.000000', NULL, 1),
(73234, 2397, 772, '<td valign="top">This is a cute baby :)  A possible improvement here would be to get a bit closer and crop off the right side of the image... nice shot :)  - jmsetzler</td>', 'This is a cute baby :)  A possible improvement here would be to get a bit closer and crop off the right side of the image... nice shot :)  - jmsetzler', '2002-06-19 13:59:00.000000', NULL, 1),
(73235, 2397, 811, '<td valign="top">Just out of curiousity -- what does it look like in black adn white?  Also, is there a particular reason the picture is turned this way.  It almost looks like the baby is flying or falling face down.  Babies sure are cute aren''t they. especially when they are asleep.</td>', 'Just out of curiousity -- what does it look like in black adn white?  Also, is there a particular reason the picture is turned this way.  It almost looks like the baby is flying or falling face down.  Babies sure are cute aren''t they. especially when they are asleep.', '2002-06-21 16:44:00.000000', NULL, 1),
(73236, 2397, 1, '<td valign="top">The blanket he''s laying out distracts from the photo. For this type of shot, I would''ve tried a solid color blanket.</td>', 'The blanket he''s laying out distracts from the photo. For this type of shot, I would''ve tried a solid color blanket.', '2002-06-21 20:23:00.000000', NULL, 1),
(73237, 2397, 1041, '<td valign="top">Congrats on the new baby, Tim! :)</td>', 'Congrats on the new baby, Tim! :)', '2002-06-24 10:48:00.000000', NULL, 0),
(73238, 2398, 741, '<td valign="top">Good try but too busy.</td>', 'Good try but too busy.', '2002-06-17 13:51:00.000000', NULL, 1),
(73239, 2398, 1944, '<td valign="top">Although it would be difficult with the light levels in your picture, it would have been nice to have more DOF. As it is, the eye is attracted to the light area on top of the flower which is a little behind the focus point. If possible it would have been better to focus about 1/3 of the way, or maybe even a little further, back from the front of the flower. Then the light part would be sharp, and even if the front was a little blured it would help the eye move to the center of interest in you picture.</td>', 'Although it would be difficult with the light levels in your picture, it would have been nice to have more DOF. As it is, the eye is attracted to the light area on top of the flower which is a little behind the focus point. If possible it would have been better to focus about 1/3 of the way, or maybe even a little further, back from the front of the flower. Then the light part would be sharp, and even if the front was a little blured it would help the eye move to the center of interest in you picture.', '2002-06-17 14:24:00.000000', NULL, 1),
(73240, 2398, 2172, '<td valign="top">Very interesting and captivating!</td>', 'Very interesting and captivating!', '2002-06-17 15:15:00.000000', NULL, 1),
(73241, 2398, 1005, '<td valign="top">Lovely shot.  Further flower appears not quite as crisp is the near one.  No other critique as this shot is that good.  Keep up the good work!<br/>Photo 9 Creativity 6 Shadows 8 total 8</td>', 'Lovely shot.  Further flower appears not quite as crisp is the near one.  No other critique as this shot is that good.  Keep up the good work!Photo 9 Creativity 6 Shadows 8 total 8', '2002-06-17 15:35:00.000000', NULL, 1),
(73242, 2398, 857, '<td valign="top">Amazing, lovely contrast between shadow and light!</td>', 'Amazing, lovely contrast between shadow and light!', '2002-06-17 16:43:00.000000', NULL, 1),
(73243, 2398, 1563, '<td valign="top">Excellent, one of my higher votes.</td>', 'Excellent, one of my higher votes.', '2002-06-17 20:57:00.000000', NULL, 1),
(73244, 2398, 2, '<td valign="top">For a black and white image, the flower itself seems to hover too much around the middle-greys.  It''s just borderline between a soft shot and a nice, contrasty shot -- and I think it should go one way or the other.</td>', 'For a black and white image, the flower itself seems to hover too much around the middle-greys.  It''s just borderline between a soft shot and a nice, contrasty shot -- and I think it should go one way or the other.', '2002-06-17 22:04:00.000000', NULL, 1),
(73245, 2398, 1856, '<td valign="top">Oh for criminy''s sake...another flower!  LOL.  I do like this but it doesn''t seem to meet the challenge.  If it does it''s by a hair.  Wish the lighting was more similar on the left and right outer petals.  Oh, if this were a ''light'' picture you''d get another pt from me.</td>', 'Oh for criminy''s sake...another flower!  LOL.  I do like this but it doesn''t seem to meet the challenge.  If it does it''s by a hair.  Wish the lighting was more similar on the left and right outer petals.  Oh, if this were a ''light'' picture you''d get another pt from me.', '2002-06-17 22:45:00.000000', NULL, 1),
(73246, 2398, 1446, '<td valign="top">Nice job with shadows here.  Excellent focus and detail.  I like the mood you created!</td>', 'Nice job with shadows here.  Excellent focus and detail.  I like the mood you created!', '2002-06-18 09:41:00.000000', NULL, 1),
(73247, 2398, 509, '<td valign="top">Nice eery quality here.</td>', 'Nice eery quality here.', '2002-06-18 15:15:00.000000', NULL, 1),
