(73258, 2402, 772, '<td valign="top">I am uninspired by the subject and it''s shadow...</td>', 'I am uninspired by the subject and it''s shadow...', '2002-06-17 17:15:00.000000', NULL, 1),
(73259, 2402, 1041, '<td valign="top">Hehehe, he has a great smile.  I think you are moving in the right direction with this one by not placing Bob in the middle of the shot.  I would''ve probably moved him even further to the left (rule of thirds).</td>', 'Hehehe, he has a great smile.  I think you are moving in the right direction with this one by not placing Bob in the middle of the shot.  I would''ve probably moved him even further to the left (rule of thirds).', '2002-06-17 18:57:00.000000', NULL, 1),
(73260, 2402, 737, '<td valign="top">Why did you choose this subject? Technically ok, but I would like to see it with more color &amp; contrast. Different lighting maybe.</td>', 'Why did you choose this subject? Technically ok, but I would like to see it with more color & contrast. Different lighting maybe.', '2002-06-17 19:54:00.000000', NULL, 1),
(73261, 2402, 138, '<td valign="top">HA!</td>', 'HA!', '2002-06-17 20:20:00.000000', NULL, 1),
(73262, 2402, 1005, '<td valign="top">Not bad, but get a brighter light, then move your light source back further and your shadow will be clearer.  In my interpretation of this challenge, the subject or the center of attention would be the shadow, not so here, the sponge overshadows your shadow. <br/>Photo 8 Creativity 5 Shadows 5 total 6</td>', 'Not bad, but get a brighter light, then move your light source back further and your shadow will be clearer.  In my interpretation of this challenge, the subject or the center of attention would be the shadow, not so here, the sponge overshadows your shadow. Photo 8 Creativity 5 Shadows 5 total 6', '2002-06-17 20:58:00.000000', NULL, 1),
(73263, 2402, 1569, '<td valign="top">I think if he had something to put his feet on it would be better.</td>', 'I think if he had something to put his feet on it would be better.', '2002-06-18 20:34:00.000000', NULL, 1),
(73264, 2402, 554, '<td valign="top">Hi Bob, good to see ya again..sharpen up a bit please otherwise good, except maybe the framing</td>', 'Hi Bob, good to see ya again..sharpen up a bit please otherwise good, except maybe the framing', '2002-06-18 21:30:00.000000', NULL, 1),
(73265, 2402, 527, '<td valign="top">I would have preferred this guy having a long, real pronounced shadow. It''s funny, though.</td>', 'I would have preferred this guy having a long, real pronounced shadow. It''s funny, though.', '2002-06-19 00:58:00.000000', NULL, 1),
(73266, 2402, 255, '<td valign="top">spongebob rules.</td>', 'spongebob rules.', '2002-06-19 06:01:00.000000', NULL, 1),
(73267, 2402, 2126, '<td valign="top">The quality on this shot is a bit poor - maybe it would be better with a stronger light (although you would have to work with the shadow a bit more). The link to the challenge is a bit tenuous too - you might want to move the doll further from the wall / nearer to the light so that the shadow will be bigger, as well as have a stronger light to make it more defined</td>', 'The quality on this shot is a bit poor - maybe it would be better with a stronger light (although you would have to work with the shadow a bit more). The link to the challenge is a bit tenuous too - you might want to move the doll further from the wall / nearer to the light so that the shadow will be bigger, as well as have a stronger light to make it more defined', '2002-06-21 13:40:00.000000', NULL, 1),
(73268, 2402, 2140, '<td valign="top">why???????????????????</td>', 'why???????????????????', '2002-06-22 23:08:00.000000', NULL, 1),
