(73321, 2407, 1485, '<td valign="top">Hey look.. there is my shadow.. the sunlight has created a copy of me on the ground.. I think i will take a picture of my own shadow..</td>', 'Hey look.. there is my shadow.. the sunlight has created a copy of me on the ground.. I think i will take a picture of my own shadow..', '2002-06-19 10:24:00.000000', NULL, 1),
