(73323, 2407, 811, '<td valign="top">The sidewalk leads my eyes one way, and the shadow almost leads another.  I think this could be effective if the shadow went more into the grass.  Otherwise, it needed to be completely on the sidewalk, I think.</td>', 'The sidewalk leads my eyes one way, and the shadow almost leads another.  I think this could be effective if the shadow went more into the grass.  Otherwise, it needed to be completely on the sidewalk, I think.', '2002-06-19 16:50:00.000000', NULL, 1),
(73324, 2407, 2263, '<td valign="top">Come on man, what''s with the title?</td>', 'Come on man, what''s with the title?', '2002-06-21 20:25:00.000000', NULL, 1),
(73325, 2407, 1, '<td valign="top">Very bland.</td>', 'Very bland.', '2002-06-23 23:13:00.000000', NULL, 1),
(73326, 2408, 92, '<td valign="top">This has some really cool effects. The only part that distracts the eye is the white at the top. The textures are great !</td>', 'This has some really cool effects. The only part that distracts the eye is the white at the top. The textures are great !', '2002-06-17 08:49:00.000000', NULL, 1),
(73327, 2408, 772, '<td valign="top">It''s a little difficult to tell that this is a chair from this perspective...</td>', 'It''s a little difficult to tell that this is a chair from this perspective...', '2002-06-17 17:47:00.000000', NULL, 1),
(73328, 2408, 2109, '<td valign="top">nice light effects</td>', 'nice light effects', '2002-06-17 19:14:00.000000', NULL, 1),
(73329, 2408, 1005, '<td valign="top">Had to stare at this one!  It''s a chair back and vertical blinds.   The extraineous blue colors confused me.  Very bright, vivid shot.  I think I would have liked this better if the bottom was cropped (two blue flares...), the top (a monitor???) and the sides, but keep the chair seat if possible!<br/>Photo 8 Creativity 7 Shadows 8 total 8</td>', 'Had to stare at this one!  It''s a chair back and vertical blinds.   The extraineous blue colors confused me.  Very bright, vivid shot.  I think I would have liked this better if the bottom was cropped (two blue flares...), the top (a monitor???) and the sides, but keep the chair seat if possible!Photo 8 Creativity 7 Shadows 8 total 8', '2002-06-17 21:02:00.000000', NULL, 1),
(73330, 2408, 1759, '<td valign="top">This would be improved (me thinks) if the books and notebook in the background were removed. It doesn''t give the appearance of a set up shot when such things are showing.</td>', 'This would be improved (me thinks) if the books and notebook in the background were removed. It doesn''t give the appearance of a set up shot when such things are showing.', '2002-06-17 22:05:00.000000', NULL, 1),
(73331, 2408, 1856, '<td valign="top">I need more of a visual explanation to be able to appreciate this.  Was there a better angle for this shot?  The junk on the floor detracts from the photo as well.  **DAYS LATER** The more I see this the more I like it.  It''s a nice image...colors and lines are great...I like how the shadows follow the grain of the wood.  It almost looks like it could be some sort of exotic wood with zebra grain.  I''m bumping my original score up.  I''ve changed my mind...everything is great except for the clutter on the floor!  : P</td>', 'I need more of a visual explanation to be able to appreciate this.  Was there a better angle for this shot?  The junk on the floor detracts from the photo as well.  **DAYS LATER** The more I see this the more I like it.  It''s a nice image...colors and lines are great...I like how the shadows follow the grain of the wood.  It almost looks like it could be some sort of exotic wood with zebra grain.  I''m bumping my original score up.  I''ve changed my mind...everything is great except for the clutter on the floor!  : P', '2002-06-17 22:40:00.000000', NULL, 1),
(73332, 2408, 1599, '<td valign="top">looks like a UFO.</td>', 'looks like a UFO.', '2002-06-18 01:58:00.000000', NULL, 1),
(73333, 2408, 1054, '<td valign="top">The lighting brings out the texture of the chair back nicely.  I wonder if a portrait orientation would have gotten rid of the dead space at the edges, though.</td>', 'The lighting brings out the texture of the chair back nicely.  I wonder if a portrait orientation would have gotten rid of the dead space at the edges, though.', '2002-06-18 12:36:00.000000', NULL, 1),
(73334, 2408, 811, '<td valign="top">I think the angle detracts from this somewhat.  Was there a way to get a more interesting shot, maybe from the side?  It may have also looked kinda cool to turn the chair 90 degrees so the shadows were perpindicular (sortof) to the grain of the wood.</td>', 'I think the angle detracts from this somewhat.  Was there a way to get a more interesting shot, maybe from the side?  It may have also looked kinda cool to turn the chair 90 degrees so the shadows were perpindicular (sortof) to the grain of the wood.', '2002-06-19 23:28:00.000000', NULL, 1),
(73335, 2408, 1037, '<td valign="top">Wow, great colours and textures. It looks like a photo of a piece of artwork made from found objects I could see in a gallery :)</td>', 'Wow, great colours and textures. It looks like a photo of a piece of artwork made from found objects I could see in a gallery :)', '2002-06-20 09:42:00.000000', NULL, 1),
(73336, 2408, 2263, '<td valign="top">What is it.</td>', 'What is it.', '2002-06-20 21:42:00.000000', NULL, 1),
(73337, 2408, 641, '<td valign="top">I like the blues in this.. my only complaint is the distracting white objects at the very top.</td>', 'I like the blues in this.. my only complaint is the distracting white objects at the very top.', '2002-06-21 16:02:00.000000', NULL, 1),
(73338, 2408, 1, '<td valign="top">Crazy loooking shot, nice shadows.</td>', 'Crazy loooking shot, nice shadows.', '2002-06-22 18:08:00.000000', NULL, 1),
(73339, 2409, 570, '<td valign="top">WAY TO FOLLOW THE CHALLENGE</td>', 'WAY TO FOLLOW THE CHALLENGE', '2002-06-17 14:36:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(73340, 2409, 1759, '<td valign="top">I love old buildings and this one is full of character, but I don''t see the connection with the shadow challenge.</td>', 'I love old buildings and this one is full of character, but I don''t see the connection with the shadow challenge.', '2002-06-17 16:01:00.000000', NULL, 1),
(73341, 2409, 2263, '<td valign="top">cool picture, but I''m not finding any shadows.</td>', 'cool picture, but I''m not finding any shadows.', '2002-06-17 16:46:00.000000', NULL, 1),
(73342, 2409, 772, '<td valign="top">I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...</td>', 'I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...', '2002-06-17 16:51:00.000000', NULL, 1),
(73343, 2409, 1041, '<td valign="top">This shot works well in b&amp;w and is pretty well composed, too.   While there are some shadows in this shot, they are not very noticeable and certainly don''t play a role in the photo (in my mind), hence the link to the challenge appears rather weak.</td>', 'This shot works well in b&w and is pretty well composed, too.   While there are some shadows in this shot, they are not very noticeable and certainly don''t play a role in the photo (in my mind), hence the link to the challenge appears rather weak.', '2002-06-17 19:03:00.000000', NULL, 1),
(73344, 2409, 203, '<td valign="top">Wonderful photo.  Lost a point for the sign focus.</td>', 'Wonderful photo.  Lost a point for the sign focus.', '2002-06-17 19:21:00.000000', NULL, 1),
(73345, 2409, 2109, '<td valign="top">excellent photo, but not much for shadows</td>', 'excellent photo, but not much for shadows', '2002-06-17 19:25:00.000000', NULL, 1),
(73346, 2409, 2158, '<td valign="top">As a picture I really like it, but I''m not sure the shadows are pronounced enough for this particular challenge.</td>', 'As a picture I really like it, but I''m not sure the shadows are pronounced enough for this particular challenge.', '2002-06-17 20:25:00.000000', NULL, 1),
(73347, 2409, 1944, '<td valign="top">I see the shadows in the photo, and the shadows in the buildings  history. Good job. If I were to make one suggestion it would be to try for a little more contrast by lightning the white a bit. I do see the effect you wanted to achieve.</td>', 'I see the shadows in the photo, and the shadows in the buildings  history. Good job. If I were to make one suggestion it would be to try for a little more contrast by lightning the white a bit. I do see the effect you wanted to achieve.', '2002-06-17 21:48:00.000000', NULL, 1),
(73348, 2409, 2235, '<td valign="top">Nice idea with B&amp;W.  I would have preferred more dramatic shadows.  Somewhat static. Great shot but not as to the title topic.</td>', 'Nice idea with B&W.  I would have preferred more dramatic shadows.  Somewhat static. Great shot but not as to the title topic.', '2002-06-17 23:18:00.000000', NULL, 1),
(73349, 2409, 1037, '<td valign="top">Very nice black and white photo. I''m sure this is getting rated down for not meeting the challenge, but I can see how the shadows add depth and mood to this shot.</td>', 'Very nice black and white photo. I''m sure this is getting rated down for not meeting the challenge, but I can see how the shadows add depth and mood to this shot.', '2002-06-18 13:19:00.000000', NULL, 1),
(73350, 2409, 1054, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2002-06-18 18:17:00.000000', NULL, 1),
(73351, 2409, 1485, '<td valign="top">this is a great poster shot, sadly.. it''s not very powerful shadow-wise</td>', 'this is a great poster shot, sadly.. it''s not very powerful shadow-wise', '2002-06-19 10:25:00.000000', NULL, 1),
(73352, 2409, 472, '<td valign="top">good bw. focus could be a littttle bit sharper. i wish i could read that sign but it may just be a function of web presentation.</td>', 'good bw. focus could be a littttle bit sharper. i wish i could read that sign but it may just be a function of web presentation.', '2002-06-19 12:27:00.000000', NULL, 1),
(73353, 2409, 2312, '<td valign="top">Subject matter would be great with more stark directional lighting.</td>', 'Subject matter would be great with more stark directional lighting.', '2002-06-19 15:42:00.000000', NULL, 1),
(73354, 2409, 1005, '<td valign="top">O.K. there are shadows on the porches, but was that the subject of your photo?  Probably not, considering your title refers to the flag on the outer wall.  I originally had you scored as a 6, but on further viewing.........Photo 8 Creativity ????? (see above)  Shadows 2 total 4</td>', 'O.K. there are shadows on the porches, but was that the subject of your photo?  Probably not, considering your title refers to the flag on the outer wall.  I originally had you scored as a 6, but on further viewing.........Photo 8 Creativity ????? (see above)  Shadows 2 total 4', '2002-06-19 17:55:00.000000', NULL, 1),
(73355, 2409, 2125, '<td valign="top">i really like this picture, not sure of the don''t tread on me tie in or the shadows but it is a helluva good pic...</td>', 'i really like this picture, not sure of the don''t tread on me tie in or the shadows but it is a helluva good pic...', '2002-06-20 14:03:00.000000', NULL, 1),
(73356, 2409, 689, '<td valign="top">Not much of a shadow here ...</td>', 'Not much of a shadow here ...', '2002-06-22 13:44:00.000000', NULL, 1),
(73357, 2409, 1061, '<td valign="top">Looks like a Matthew Brady photo.  In this case that is a GOOD thing.</td>', 'Looks like a Matthew Brady photo.  In this case that is a GOOD thing.', '2002-06-23 05:02:00.000000', NULL, 1),
(73358, 2409, 1, '<td valign="top">Nice shot, but the shadows jsut aren''t prominent.</td>', 'Nice shot, but the shadows jsut aren''t prominent.', '2002-06-23 20:09:00.000000', NULL, 1),
(73359, 2409, 734, '<td valign="top">Great pic, but I just noticed that in your detail section that the image was taken in January, which does not fall into the aproved time slot for the shadows challenge.  I wonder why that wasnt cought,.. oh well nice pic.</td>', 'Great pic, but I just noticed that in your detail section that the image was taken in January, which does not fall into the aproved time slot for the shadows challenge.  I wonder why that wasnt cought,.. oh well nice pic.', '2002-06-24 20:02:00.000000', NULL, 0),
(73360, 2411, 570, '<td valign="top">I don''t see a shadow here, do you?</td>', 'I don''t see a shadow here, do you?', '2002-06-17 14:35:00.000000', NULL, 1),
(73361, 2411, 2060, '<td valign="top">Not a Shadow!</td>', 'Not a Shadow!', '2002-06-17 14:53:00.000000', NULL, 1),
(73362, 2411, 1005, '<td valign="top">Really nice, maybe a little too much framing, but otherwise wow.  I like the sun-star effect.  Shot works well in B&amp;W.<br/>Photo 9 Creativity 8 Shadows 9 total 9</td>', 'Really nice, maybe a little too much framing, but otherwise wow.  I like the sun-star effect.  Shot works well in B&W.Photo 9 Creativity 8 Shadows 9 total 9', '2002-06-17 16:52:00.000000', NULL, 1),
(73363, 2411, 1944, '<td valign="top">Nice photo but a little over sharpened. I cand see some edge effects on high contrast boundries.</td>', 'Nice photo but a little over sharpened. I cand see some edge effects on high contrast boundries.', '2002-06-17 21:39:00.000000', NULL, 1),
(73364, 2411, 2199, '<td valign="top">very creative composition</td>', 'very creative composition', '2002-06-17 22:55:00.000000', NULL, 1),
(73365, 2411, 1054, '<td valign="top">I love that kind of window.  Well done.</td>', 'I love that kind of window.  Well done.', '2002-06-18 12:44:00.000000', NULL, 1),
(73366, 2411, 772, '<td valign="top">The sun flare in this photo is excellent.. I also love the way the hand is silhouetted in this image.  The only improvement that I think is possible in this photo would be a vertical crop to remove the extra darkness from both sides... great shot!</td>', 'The sun flare in this photo is excellent.. I also love the way the hand is silhouetted in this image.  The only improvement that I think is possible in this photo would be a vertical crop to remove the extra darkness from both sides... great shot!', '2002-06-18 19:34:00.000000', NULL, 1),
(73367, 2411, 811, '<td valign="top">I like your use of shadows and silhouette combined here.  To me, this is an elegant photo.</td>', 'I like your use of shadows and silhouette combined here.  To me, this is an elegant photo.', '2002-06-20 01:06:00.000000', NULL, 1),
(73368, 2411, 573, '<td valign="top">I feel the challenge this week should be the shadow as the subject of the picture.  Don''t get me wrong, i realy like high contrast backlit photos and the star filter is a great touch.</td>', 'I feel the challenge this week should be the shadow as the subject of the picture.  Don''t get me wrong, i realy like high contrast backlit photos and the star filter is a great touch.', '2002-06-20 16:33:00.000000', NULL, 1),
(73369, 2411, 1, '<td valign="top">Interesting, ince flare.  I wish the hand didn''t get lost in the bottom of the window... try repositioning.</td>', 'Interesting, ince flare.  I wish the hand didn''t get lost in the bottom of the window... try repositioning.', '2002-06-23 17:25:00.000000', NULL, 1),
(73370, 2419, 1856, '<td valign="top">Nice photo.  I wish the crop was done to include the full edge of the outter circle though.  I think I see a reflection from blinds on the glass.  The face and shadows may have photographed better with use of an artificial light source in a room with no windows.</td>', 'Nice photo.  I wish the crop was done to include the full edge of the outter circle though.  I think I see a reflection from blinds on the glass.  The face and shadows may have photographed better with use of an artificial light source in a room with no windows.', '2002-06-17 12:01:00.000000', NULL, 1),
(73371, 2419, 2243, '<td valign="top">better if the sides and bottom weren''t chopped off</td>', 'better if the sides and bottom weren''t chopped off', '2002-06-17 14:28:00.000000', NULL, 1),
(73372, 2419, 1005, '<td valign="top">Nice shot.  (With a name like Danbury, you wouldn''t think made in china.)  Secondary reflections at 10 O''Clock, plus flares at 2 and 4.  Also not certain I like the cropping, was there a problem with the outside edges of the clock?  (Did it just look better this way?)<br/>Photo 8 Creativity 6 Shadows 7 total 7</td>', 'Nice shot.  (With a name like Danbury, you wouldn''t think made in china.)  Secondary reflections at 10 O''Clock, plus flares at 2 and 4.  Also not certain I like the cropping, was there a problem with the outside edges of the clock?  (Did it just look better this way?)Photo 8 Creativity 6 Shadows 7 total 7', '2002-06-17 15:39:00.000000', NULL, 1),
(73373, 2419, 857, '<td valign="top">Somewhat stale, cool picture but the subject is boring</td>', 'Somewhat stale, cool picture but the subject is boring', '2002-06-17 16:41:00.000000', NULL, 1),
(73374, 2419, 2094, '<td valign="top">A little off-tilt, but a nice shot... The detail and lighting look very good.</td>', 'A little off-tilt, but a nice shot... The detail and lighting look very good.', '2002-06-17 22:47:00.000000', NULL, 1),
(73375, 2419, 2216, '<td valign="top">neat shot, that needs to be hanging in a lawers office!</td>', 'neat shot, that needs to be hanging in a lawers office!', '2002-06-18 01:44:00.000000', NULL, 1),
(73376, 2419, 772, '<td valign="top">This is a very nicely composed photo.. I think a fill flash would have gotten rid of the shadows on the face of the clock though... btw- just kidding about the fill flash :)  Good work!</td>', 'This is a very nicely composed photo.. I think a fill flash would have gotten rid of the shadows on the face of the clock though... btw- just kidding about the fill flash :)  Good work!', '2002-06-18 12:20:00.000000', NULL, 1),
(73377, 2419, 1054, '<td valign="top">This image should be rotated slightly counterclockwise, otherwise very good.</td>', 'This image should be rotated slightly counterclockwise, otherwise very good.', '2002-06-18 17:10:00.000000', NULL, 1),
(73378, 2419, 1037, '<td valign="top">Very nice composition. The shadows here add a great element, some extra depth, some curves that break the symmetry of the clock face, etc.</td>', 'Very nice composition. The shadows here add a great element, some extra depth, some curves that break the symmetry of the clock face, etc.', '2002-06-19 04:31:00.000000', NULL, 1),
(73379, 2419, 2199, '<td valign="top">Nice idea, excellent title. (I might like the photo a bit more if the crop were either in tighter, or come out a bit so we can see the entire curved shape of the clock).</td>', 'Nice idea, excellent title. (I might like the photo a bit more if the crop were either in tighter, or come out a bit so we can see the entire curved shape of the clock).', '2002-06-19 13:58:00.000000', NULL, 1),
(73380, 2419, 1, '<td valign="top">Would''ve been more interesting with a better time... maybe 12?</td>', 'Would''ve been more interesting with a better time... maybe 12?', '2002-06-22 12:30:00.000000', NULL, 1),
(73381, 2419, 1041, '<td valign="top">Nice clock.  Did you consider showing either the whole clock or even just a partial of the clock face?  This way it looks a little ''just cut off at the edges'' to me.  But that may just be my opinion.  Other than that, good focus, looks good in b&amp;w.</td>', 'Nice clock.  Did you consider showing either the whole clock or even just a partial of the clock face?  This way it looks a little ''just cut off at the edges'' to me.  But that may just be my opinion.  Other than that, good focus, looks good in b&w.', '2002-06-22 15:50:00.000000', NULL, 1),
(73382, 2421, 1054, '<td valign="top">ROFL! Great composition, and funny, too!</td>', 'ROFL! Great composition, and funny, too!', '2002-06-17 01:55:00.000000', NULL, 1),
(73383, 2421, 570, '<td valign="top">nice and blurry</td>', 'nice and blurry', '2002-06-17 14:34:00.000000', NULL, 1),
(73384, 2421, 1031, '<td valign="top">Love your title, but why not flop the image to match the most commonly seen profile?</td>', 'Love your title, but why not flop the image to match the most commonly seen profile?', '2002-06-17 15:30:00.000000', NULL, 1),
(73385, 2421, 1041, '<td valign="top">This shot certainly qualifies for the shadow competition.  Placement of it in the photo is ok, too.  However, I''m not very excited looking at the shot, sorry.</td>', 'This shot certainly qualifies for the shadow competition.  Placement of it in the photo is ok, too.  However, I''m not very excited looking at the shot, sorry.', '2002-06-17 16:15:00.000000', NULL, 1),
(73386, 2421, 1599, '<td valign="top">OK</td>', 'OK', '2002-06-18 01:11:00.000000', NULL, 1),
(73387, 2421, 1759, '<td valign="top">I don''t think Hitchcock was quite as lumpy as Bubba looks in this one. Bubba is also a bit fuzzy, but good effort.</td>', 'I don''t think Hitchcock was quite as lumpy as Bubba looks in this one. Bubba is also a bit fuzzy, but good effort.', '2002-06-18 02:02:00.000000', NULL, 1),
(73388, 2421, 1446, '<td valign="top">Too funny!  Great concept! I would have liked to see a little better definintion of the shadow, but then again.......its a shadow.......Overall a 7.</td>', 'Too funny!  Great concept! I would have liked to see a little better definintion of the shadow, but then again.......its a shadow.......Overall a 7.', '2002-06-18 09:40:00.000000', NULL, 1),
(73389, 2421, 1569, '<td valign="top">Good one !! The shadow edges need help. A little more contrast is needed.</td>', 'Good one !! The shadow edges need help. A little more contrast is needed.', '2002-06-18 19:57:00.000000', NULL, 1),
(73390, 2421, 554, '<td valign="top">hi Bubba,  great idea</td>', 'hi Bubba,  great idea', '2002-06-18 23:49:00.000000', NULL, 1),
(73391, 2421, 1856, '<td valign="top">Too blurry for me.</td>', 'Too blurry for me.', '2002-06-19 12:21:00.000000', NULL, 1),
(73392, 2421, 2199, '<td valign="top">Very funny idea. Actually I''m tired of seeing "people shadows", but you get a few extra points for humour. The photo also does a good job of reminding me of the original Hitchcock shadow....</td>', 'Very funny idea. Actually I''m tired of seeing "people shadows", but you get a few extra points for humour. The photo also does a good job of reminding me of the original Hitchcock shadow....', '2002-06-19 13:20:00.000000', NULL, 1),
(73393, 2421, 1, '<td valign="top">Very funny, I wish the shadow was more crisp though... try getting closer to the wall?</td>', 'Very funny, I wish the shadow was more crisp though... try getting closer to the wall?', '2002-06-19 16:00:00.000000', NULL, 1),
(73394, 2421, 772, '<td valign="top">Cool hat :)</td>', 'Cool hat :)', '2002-06-20 00:39:00.000000', NULL, 1),
(73395, 2421, 875, '<td valign="top">Great idea!  I wish the shadow was a little less fuzzy.</td>', 'Great idea!  I wish the shadow was a little less fuzzy.', '2002-06-20 20:01:00.000000', NULL, 1),
(73396, 2421, 689, '<td valign="top">Bubba is pregnant ....</td>', 'Bubba is pregnant ....', '2002-06-21 19:27:00.000000', NULL, 1),
(73397, 2421, 1061, '<td valign="top">You get an extra point for making me laugh!</td>', 'You get an extra point for making me laugh!', '2002-06-23 04:34:00.000000', NULL, 1),
(73398, 2422, 1054, '<td valign="top">Good composition, and the sepia was a good choice.</td>', 'Good composition, and the sepia was a good choice.', '2002-06-17 09:06:00.000000', NULL, 1),
(73399, 2422, 1856, '<td valign="top">I wonder if you could have gotten the shadow more crisply with some lighting adjustment.  Good idea.  Implementation needs a little work.  I think I had the same problem.</td>', 'I wonder if you could have gotten the shadow more crisply with some lighting adjustment.  Good idea.  Implementation needs a little work.  I think I had the same problem.', '2002-06-17 10:59:00.000000', NULL, 1),
(73400, 2422, 142, '<td valign="top">Beautiful.  The coloring of the photo is perfect.</td>', 'Beautiful.  The coloring of the photo is perfect.', '2002-06-17 12:36:00.000000', NULL, 1),
(73401, 2422, 1446, '<td valign="top">I really like the color in this shot.  The focus is perfect.  The shadow is interesting.</td>', 'I really like the color in this shot.  The focus is perfect.  The shadow is interesting.', '2002-06-17 13:47:00.000000', NULL, 1),
(73402, 2422, 441, '<td valign="top">good shadows here</td>', 'good shadows here', '2002-06-17 18:04:00.000000', NULL, 1),
(73403, 2422, 2235, '<td valign="top">Overall good concept. Not too dramatic to catch full eye.</td>', 'Overall good concept. Not too dramatic to catch full eye.', '2002-06-17 23:17:00.000000', NULL, 1),
(73404, 2422, 1599, '<td valign="top">nice angle, but not enough shadow</td>', 'nice angle, but not enough shadow', '2002-06-18 00:54:00.000000', NULL, 1),
(73405, 2422, 1792, '<td valign="top">Good composition.  The simplicity is nice.</td>', 'Good composition.  The simplicity is nice.', '2002-06-18 01:40:00.000000', NULL, 1),
