(73500, 2429, 1599, '<td valign="top">Interesting, nice use of shadows</td>', 'Interesting, nice use of shadows', '2002-06-18 01:19:00.000000', NULL, 1),
(73501, 2429, 734, '<td valign="top">I would love to see this in B&amp;W,.... great idea i love the shadows</td>', 'I would love to see this in B&W,.... great idea i love the shadows', '2002-06-18 03:39:00.000000', NULL, 1),
(73502, 2429, 554, '<td valign="top">nice idea and well done too----we should put our animals together sometime--10</td>', 'nice idea and well done too----we should put our animals together sometime--10', '2002-06-18 21:33:00.000000', NULL, 1),
(73503, 2429, 2152, '<td valign="top">Great use of shadows!  The shot appears a little underexposed and blurry, but I still like it a lot.  Also, I might have cropped differently to lose the floor and get the whole plant in the shot.  Some more contrast would help, as well.</td>', 'Great use of shadows!  The shot appears a little underexposed and blurry, but I still like it a lot.  Also, I might have cropped differently to lose the floor and get the whole plant in the shot.  Some more contrast would help, as well.', '2002-06-18 23:48:00.000000', NULL, 1),
(73504, 2429, 1054, '<td valign="top">The angle of the shot, with the apparent revelation that this was taken indoors, hurts this shot -- the bottom right corner is a distraction.</td>', 'The angle of the shot, with the apparent revelation that this was taken indoors, hurts this shot -- the bottom right corner is a distraction.', '2002-06-19 06:31:00.000000', NULL, 1),
(73505, 2429, 2221, '<td valign="top">creative! a little less contrast for my taste and maybe you should have taken the shot more from the front and a little below (to make the giraffe hight, it''s a tall animal)</td>', 'creative! a little less contrast for my taste and maybe you should have taken the shot more from the front and a little below (to make the giraffe hight, it''s a tall animal)', '2002-06-19 09:45:00.000000', NULL, 1),
