(73507, 2429, 1, '<td valign="top">Nicely framed, great idea.  I''d like to see what you used for this shot.</td>', 'Nicely framed, great idea.  I''d like to see what you used for this shot.', '2002-06-23 19:21:00.000000', NULL, 1),
(73508, 2430, 1446, '<td valign="top">I really like the rich color of this shot.  Good use of object in the hot spots.  Very dramatic feeling.......One of my top 5 pics for the week.</td>', 'I really like the rich color of this shot.  Good use of object in the hot spots.  Very dramatic feeling.......One of my top 5 pics for the week.', '2002-06-17 13:51:00.000000', NULL, 1),
