(73510, 2430, 2172, '<td valign="top">I like this one - very much like an ad.</td>', 'I like this one - very much like an ad.', '2002-06-17 16:15:00.000000', NULL, 1),
(73511, 2430, 1041, '<td valign="top">I like the shadow, but it''s competing with the highlights on the corkscrew because they are the same color as the highlights in the shadow.</td>', 'I like the shadow, but it''s competing with the highlights on the corkscrew because they are the same color as the highlights in the shadow.', '2002-06-17 17:20:00.000000', NULL, 1),
(73512, 2430, 441, '<td valign="top">georgeous colour!</td>', 'georgeous colour!', '2002-06-17 18:24:00.000000', NULL, 1),
(73513, 2430, 2109, '<td valign="top">good shadow effect.  Perhaps a little more light would really make this stand out</td>', 'good shadow effect.  Perhaps a little more light would really make this stand out', '2002-06-17 18:52:00.000000', NULL, 1),
