(73516, 2430, 1759, '<td valign="top">Nice atmoshpere in this photo. You got the shadow and it actually enhances the photo! I would do a bit more sharpening for this one, but regardless, it is good and I really like it.</td>', 'Nice atmoshpere in this photo. You got the shadow and it actually enhances the photo! I would do a bit more sharpening for this one, but regardless, it is good and I really like it.', '2002-06-17 21:50:00.000000', NULL, 1),
(73517, 2430, 2235, '<td valign="top">Nice idea. Color makes impact with this photo. Need a bit more focus for my taste but well done.</td>', 'Nice idea. Color makes impact with this photo. Need a bit more focus for my taste but well done.', '2002-06-17 23:26:00.000000', NULL, 1),
(73518, 2430, 1599, '<td valign="top">Not enough color in my opinion</td>', 'Not enough color in my opinion', '2002-06-18 01:55:00.000000', NULL, 1),
(73519, 2430, 1, '<td valign="top">Nicely setup, the colors are pretty interesting, they work well to set the mood.</td>', 'Nicely setup, the colors are pretty interesting, they work well to set the mood.', '2002-06-18 09:03:00.000000', NULL, 1),
(73520, 2430, 1005, '<td valign="top">Interesting shot, the elements in this shot are great, but the corkscrew doesn''t work, something just "looks" wrong, can''t place it.  Overall darkish.<br/>Photo 9 Creativity 7 Shadows 8 total 8 ** I really like the glass and it''s shadow/light shining through, and the table. **</td>', 'Interesting shot, the elements in this shot are great, but the corkscrew doesn''t work, something just "looks" wrong, can''t place it.  Overall darkish.Photo 9 Creativity 7 Shadows 8 total 8 ** I really like the glass and it''s shadow/light shining through, and the table. **', '2002-06-18 14:04:00.000000', NULL, 1),
(73521, 2430, 1054, '<td valign="top">I like the shadow through the glass here. Good use of lighting.</td>', 'I like the shadow through the glass here. Good use of lighting.', '2002-06-18 17:50:00.000000', NULL, 1),
(73522, 2430, 2217, '<td valign="top">Too dark, but very interesting, nice composition.</td>', 'Too dark, but very interesting, nice composition.', '2002-06-19 01:38:00.000000', NULL, 1),
(73523, 2430, 2221, '<td valign="top">nice mood. but either the quality of the jpeg is bad or the picture is a little bit blurred.</td>', 'nice mood. but either the quality of the jpeg is bad or the picture is a little bit blurred.', '2002-06-19 09:13:00.000000', NULL, 1),
(73524, 2430, 1783, '<td valign="top">Reminds me of a soothing evening sitting at home reading a book.  Very nice picture.</td>', 'Reminds me of a soothing evening sitting at home reading a book.  Very nice picture.', '2002-06-19 09:26:00.000000', NULL, 1),
(73525, 2430, 1037, '<td valign="top">Very nice, rich colours and lighting. The composition seems a bit blocky though, with the glass, bottle, corkscrew and shadow all forming a rectangle of sorts.</td>', 'Very nice, rich colours and lighting. The composition seems a bit blocky though, with the glass, bottle, corkscrew and shadow all forming a rectangle of sorts.', '2002-06-20 09:09:00.000000', NULL, 1),
(73526, 2430, 772, '<td valign="top">Nice!  I love the warmth of the color in this shot... excellent work! = 9 - jmsetzler</td>', 'Nice!  I love the warmth of the color in this shot... excellent work! = 9 - jmsetzler', '2002-06-20 20:16:00.000000', NULL, 1),
(73527, 2430, 641, '<td valign="top">Great set up there. I like the gold tones.</td>', 'Great set up there. I like the gold tones.', '2002-06-21 15:55:00.000000', NULL, 1),
(73528, 2430, 2317, '<td valign="top">Nice.... try to clear it a little bit</td>', 'Nice.... try to clear it a little bit', '2002-06-22 23:04:00.000000', NULL, 1),
(73529, 2430, 1061, '<td valign="top">Excellent, could be an ad for Mumm''s</td>', 'Excellent, could be an ad for Mumm''s', '2002-06-23 04:36:00.000000', NULL, 1),
(73530, 2433, 1856, '<td valign="top">Love this for it''s simplicity...great texture too.</td>', 'Love this for it''s simplicity...great texture too.', '2002-06-17 11:09:00.000000', NULL, 1),
(73531, 2433, 2094, '<td valign="top">Awesome simplicity and composition here! I love the soft color of the light, but the very sharp and precise focus. Great photo.</td>', 'Awesome simplicity and composition here! I love the soft color of the light, but the very sharp and precise focus. Great photo.', '2002-06-17 11:13:00.000000', NULL, 1),
(73532, 2433, 772, '<td valign="top">What''s a clou?</td>', 'What''s a clou?', '2002-06-17 18:23:00.000000', NULL, 1),
(73533, 2433, 1005, '<td valign="top">Well, the shot is perfect, but humblely speaking, dull/plain/unexciting.  A bit harsh glare under the head of the nail, too.  Please explain your title next week, my dumb, but I don''t get it.  Photo 8 Creativity 5 Shadows 6 total 6</td>', 'Well, the shot is perfect, but humblely speaking, dull/plain/unexciting.  A bit harsh glare under the head of the nail, too.  Please explain your title next week, my dumb, but I don''t get it.  Photo 8 Creativity 5 Shadows 6 total 6', '2002-06-17 18:47:00.000000', NULL, 1),
(73534, 2433, 1563, '<td valign="top">Very nice setup.  Picture is great. one of my high votes this week.</td>', 'Very nice setup.  Picture is great. one of my high votes this week.', '2002-06-17 20:54:00.000000', NULL, 1),
(73535, 2433, 1599, '<td valign="top">Huh?</td>', 'Huh?', '2002-06-18 02:32:00.000000', NULL, 1),
