(73537, 2433, 1054, '<td valign="top">Simple and elegant.</td>', 'Simple and elegant.', '2002-06-18 17:49:00.000000', NULL, 1),
(73538, 2433, 1175, '<td valign="top">I like it.  Very simple.  I would have prefered a harder shadow of that nail to work with the blackness above and below the piece of wood.</td>', 'I like it.  Very simple.  I would have prefered a harder shadow of that nail to work with the blackness above and below the piece of wood.', '2002-06-18 21:40:00.000000', NULL, 1),
