INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(73540, 2433, 1037, '<td valign="top">Very simple but strongly composed.</td>', 'Very simple but strongly composed.', '2002-06-19 08:09:00.000000', NULL, 1),
(73541, 2433, 811, '<td valign="top">I really like the composition of this picture, and the simplicity of the shadows.  It has good depth.  good job.</td>', 'I really like the composition of this picture, and the simplicity of the shadows.  It has good depth.  good job.', '2002-06-19 15:57:00.000000', NULL, 1),
(73542, 2433, 1, '<td valign="top">Great DOF, the lighting is superb.</td>', 'Great DOF, the lighting is superb.', '2002-06-21 20:44:00.000000', NULL, 1),
(73543, 2433, 2004, '<td valign="top">Thank you all for your nice comments :) This was my very first submission to dpchallenge, be sure it will not be the last, I liked the experience ! Oh, and by the way, "un clou" is just the french word for "a nail"...</td>', 'Thank you all for your nice comments :) This was my very first submission to dpchallenge, be sure it will not be the last, I liked the experience ! Oh, and by the way, "un clou" is just the french word for "a nail"...', '2002-06-24 18:36:00.000000', NULL, 0),
(73544, 2435, 2075, '<td valign="top">Hehe...funny!</td>', 'Hehe...funny!', '2002-06-17 01:21:00.000000', NULL, 1),
(73545, 2435, 718, '<td valign="top">Cleaver idea, personally getting tired of the studio watch shots. I give you an 8 anyway.</td>', 'Cleaver idea, personally getting tired of the studio watch shots. I give you an 8 anyway.', '2002-06-17 01:25:00.000000', NULL, 1),
(73546, 2435, 1054, '<td valign="top">Good execution, and I love the title.</td>', 'Good execution, and I love the title.', '2002-06-17 02:09:00.000000', NULL, 1),
(73547, 2435, 1944, '<td valign="top">Nice product shot. I think there should have been a little more DOF in front of the clock face. The blured cover is a little distracting. To me, the shadow isn''t as much a design element as it is something that just happened.</td>', 'Nice product shot. I think there should have been a little more DOF in front of the clock face. The blured cover is a little distracting. To me, the shadow isn''t as much a design element as it is something that just happened.', '2002-06-17 02:28:00.000000', NULL, 1),
(73548, 2435, 1856, '<td valign="top">wow.  great photo!  seems like a little lighting from the front may have improved it.</td>', 'wow.  great photo!  seems like a little lighting from the front may have improved it.', '2002-06-17 11:20:00.000000', NULL, 1),
(73549, 2435, 1707, '<td valign="top">love the good focus and sharpness</td>', 'love the good focus and sharpness', '2002-06-17 12:00:00.000000', NULL, 1),
(73550, 2435, 1658, '<td valign="top">creative idea.  i would have liked an even stonger shadow being cast off of the subject.  but nicely done.</td>', 'creative idea.  i would have liked an even stonger shadow being cast off of the subject.  but nicely done.', '2002-06-17 13:21:00.000000', NULL, 1),
(73551, 2435, 1897, '<td valign="top">Very good photo, but the shadow it pretty weak.</td>', 'Very good photo, but the shadow it pretty weak.', '2002-06-17 13:37:00.000000', NULL, 1),
(73552, 2435, 570, '<td valign="top">witty</td>', 'witty', '2002-06-17 14:36:00.000000', NULL, 1),
(73553, 2435, 1759, '<td valign="top">Very crisp macro shot. I love pocket watches, and your presentation of this one is excellent. Nice clean background and a very simple and tasteful arrangement. However, I see two shadows and neither is well defined, otherwise a very nice photo.</td>', 'Very crisp macro shot. I love pocket watches, and your presentation of this one is excellent. Nice clean background and a very simple and tasteful arrangement. However, I see two shadows and neither is well defined, otherwise a very nice photo.', '2002-06-17 16:00:00.000000', NULL, 1),
(73554, 2435, 1005, '<td valign="top">Wonderful still.  (stopped the motion of the second hand perfectly!)  Less light sources or main light source further back would have made a more distinct shadow.  Light flare at 10 O''Clock.  I would have liked a cleaner reflection on the other side of the watch, between 2 and 3 (see the dark matter?)  This shot reminds me of a previous winner, but it was a super clean set up, probably in a studio.  Seems like I picked on this quite a bit, but I really like it.  Keep up the good work!  Photo 10 Creativity 6 Shadows 8 total 8</td>', 'Wonderful still.  (stopped the motion of the second hand perfectly!)  Less light sources or main light source further back would have made a more distinct shadow.  Light flare at 10 O''Clock.  I would have liked a cleaner reflection on the other side of the watch, between 2 and 3 (see the dark matter?)  This shot reminds me of a previous winner, but it was a super clean set up, probably in a studio.  Seems like I picked on this quite a bit, but I really like it.  Keep up the good work!  Photo 10 Creativity 6 Shadows 8 total 8', '2002-06-17 16:25:00.000000', NULL, 1),
(73555, 2435, 327, '<td valign="top">O'' my socks just flew across the room!! Love this, great job. ooooyour so clever.</td>', 'O'' my socks just flew across the room!! Love this, great job. ooooyour so clever.', '2002-06-17 16:46:00.000000', NULL, 1),
(73556, 2435, 203, '<td valign="top">Very nice photo.  Yes there is a shadow but it seems so secondary to the subject.</td>', 'Very nice photo.  Yes there is a shadow but it seems so secondary to the subject.', '2002-06-17 19:25:00.000000', NULL, 1),
(73557, 2435, 2199, '<td valign="top">haha....nice idea. Also like the composition, and the depth of field used.</td>', 'haha....nice idea. Also like the composition, and the depth of field used.', '2002-06-17 20:04:00.000000', NULL, 1),
(73558, 2435, 1882, '<td valign="top">Clever, well shot!</td>', 'Clever, well shot!', '2002-06-18 10:44:00.000000', NULL, 1),
(73559, 2435, 1041, '<td valign="top">Beautiful clock, and well photographed, good composition.  Also like the title.  For a shadow challenge, I wish the shadow was a little more pronounced.  Still, I like the shot.</td>', 'Beautiful clock, and well photographed, good composition.  Also like the title.  For a shadow challenge, I wish the shadow was a little more pronounced.  Still, I like the shot.', '2002-06-18 14:48:00.000000', NULL, 1),
(73560, 2435, 1569, '<td valign="top">This is the one--great picture---exellent lighting!!!</td>', 'This is the one--great picture---exellent lighting!!!', '2002-06-18 19:06:00.000000', NULL, 1),
(73561, 2435, 772, '<td valign="top">Very nice work!  The 5 o''clock shadow concept here is definitely a good idea... I didn''t even need to see the title of this shot to catch that :)  The photo execution is GREAT and the composition is nice as well.. I''m looking at how you applied the rule of thirds with the clock... It''s leaving a little blank space on the right side of the frame.  I wonder if a little tighter crop would be better?  I''m not sure... great shot! = 9</td>', 'Very nice work!  The 5 o''clock shadow concept here is definitely a good idea... I didn''t even need to see the title of this shot to catch that :)  The photo execution is GREAT and the composition is nice as well.. I''m looking at how you applied the rule of thirds with the clock... It''s leaving a little blank space on the right side of the frame.  I wonder if a little tighter crop would be better?  I''m not sure... great shot! = 9', '2002-06-18 20:37:00.000000', NULL, 1),
(73562, 2435, 1585, '<td valign="top">Ha Ha Ha Ha. Cool.</td>', 'Ha Ha Ha Ha. Cool.', '2002-06-18 22:16:00.000000', NULL, 1),
(73563, 2435, 1793, '<td valign="top">i love the play on words. althought i''d probably try to light it so the shadow is more pronounced, that would create harsher reflections on the watch. a dillemma..</td>', 'i love the play on words. althought i''d probably try to light it so the shadow is more pronounced, that would create harsher reflections on the watch. a dillemma..', '2002-06-19 02:56:00.000000', NULL, 1),
(73564, 2435, 1599, '<td valign="top">Very Funny, I was waiting for a person to come on the screen</td>', 'Very Funny, I was waiting for a person to come on the screen', '2002-06-21 18:19:00.000000', NULL, 1),
(73565, 2435, 748, '<td valign="top">Great photo, wish the shadows had been more prominent.</td>', 'Great photo, wish the shadows had been more prominent.', '2002-06-21 19:05:00.000000', NULL, 1),
(73566, 2435, 2111, '<td valign="top">Nice job but enough with the watches. lol (7)</td>', 'Nice job but enough with the watches. lol (7)', '2002-06-22 11:11:00.000000', NULL, 1),
(73567, 2435, 1, '<td valign="top">Nicely shot, good detail.  I like how this shot, unlike the other clock one, set it to a meaningful time.</td>', 'Nicely shot, good detail.  I like how this shot, unlike the other clock one, set it to a meaningful time.', '2002-06-23 19:20:00.000000', NULL, 1),
(73568, 2435, 661, '<td valign="top">Beautiful picture of the watch.  Creative title but not so great on the shadow.  Still nice effort.</td>', 'Beautiful picture of the watch.  Creative title but not so great on the shadow.  Still nice effort.', '2002-06-24 00:09:00.000000', NULL, 1),
(73569, 2435, 1569, '<td valign="top">I thought this one was the best shot of the week---I gave it a solid 10!!!!!</td>', 'I thought this one was the best shot of the week---I gave it a solid 10!!!!!', '2002-06-24 09:11:00.000000', NULL, 0),
(73570, 2437, 2193, '<td valign="top">I like the title... 8^D</td>', 'I like the title... 8^D', '2002-06-17 04:13:00.000000', NULL, 1),
(73571, 2437, 92, '<td valign="top">Great shadow!!! I would like to see this with less background and a closer crop:)</td>', 'Great shadow!!! I would like to see this with less background and a closer crop:)', '2002-06-17 09:16:00.000000', NULL, 1),
(73572, 2437, 570, '<td valign="top">good</td>', 'good', '2002-06-17 14:40:00.000000', NULL, 1),
(73573, 2437, 2172, '<td valign="top">Great!</td>', 'Great!', '2002-06-17 16:38:00.000000', NULL, 1),
(73574, 2437, 2267, '<td valign="top">A tigher cropping would have been better by focusing it more on the snail as it is quite empty on the foreground.</td>', 'A tigher cropping would have been better by focusing it more on the snail as it is quite empty on the foreground.', '2002-06-17 17:15:00.000000', NULL, 1),
(73575, 2437, 1175, '<td valign="top">HA you are copying me!!! :)  When taking pictures of critters get down on the same plane as them.</td>', 'HA you are copying me!!! :)  When taking pictures of critters get down on the same plane as them.', '2002-06-17 17:46:00.000000', NULL, 1),
(73576, 2437, 2109, '<td valign="top">horizontal orientation and allowing the snail to fill the picture would have made this a great photo</td>', 'horizontal orientation and allowing the snail to fill the picture would have made this a great photo', '2002-06-17 19:10:00.000000', NULL, 1),
(73577, 2437, 2199, '<td valign="top">very nice!</td>', 'very nice!', '2002-06-17 20:22:00.000000', NULL, 1),
(73578, 2437, 1759, '<td valign="top">I like snails. It was nice of this one to pose for you while you snapped it''s picture. Since it is moving up and to the right, I would probably have framed it lower and maybe as a landscape view.</td>', 'I like snails. It was nice of this one to pose for you while you snapped it''s picture. Since it is moving up and to the right, I would probably have framed it lower and maybe as a landscape view.', '2002-06-17 21:14:00.000000', NULL, 1),
(73579, 2437, 2, '<td valign="top">Great shot and great title.  Is the snail just slightly out of focus, or am I going blind from voting on all of these? :)</td>', 'Great shot and great title.  Is the snail just slightly out of focus, or am I going blind from voting on all of these? :)', '2002-06-17 22:08:00.000000', NULL, 1),
