(73582, 2437, 1054, '<td valign="top">Nice capture and detail.</td>', 'Nice capture and detail.', '2002-06-18 15:36:00.000000', NULL, 1),
(73583, 2437, 1585, '<td valign="top">This is nice. The concrete looks hot, it would be cool if the snail was going real fast and a little blured. HA HA HA HA. I don''t get paid to tell jokes.</td>', 'This is nice. The concrete looks hot, it would be cool if the snail was going real fast and a little blured. HA HA HA HA. I don''t get paid to tell jokes.', '2002-06-18 22:01:00.000000', NULL, 1),
(73584, 2437, 2110, '<td valign="top">The texture also has shadows! Nice composition..</td>', 'The texture also has shadows! Nice composition..', '2002-06-20 07:31:00.000000', NULL, 1),
(73585, 2437, 772, '<td valign="top">Very nice!  This is an excellent shadow... the depth of field on this photo is almost perfect also.. maybe just a touch more but it''s ok as is :) I like the way the concrete texture distorts the shadow of this snail... good work! - jmsetzler</td>', 'Very nice!  This is an excellent shadow... the depth of field on this photo is almost perfect also.. maybe just a touch more but it''s ok as is :) I like the way the concrete texture distorts the shadow of this snail... good work! - jmsetzler', '2002-06-20 10:10:00.000000', NULL, 1),
(73586, 2437, 2125, '<td valign="top">very good did you also take toad on the road?  ;-)</td>', 'very good did you also take toad on the road?  ;-)', '2002-06-20 14:07:00.000000', NULL, 1),
