INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(73740, 2448, 1721, '<td valign="top">I can''t figure how you did this without editing....</td>', 'I can''t figure how you did this without editing....', '2002-06-23 23:05:00.000000', NULL, 1),
(73741, 2448, 2109, '<td valign="top">Thanks for all the comments... kept me entertained during the voting week.<br/><br/>This image was recommended for disqualification.  Good thing I had the original with EXIF data available ;)  Thanks to those that recommended it... I enjoy being kept on my toes.<br/><br/>Here''s how it was done... the bottle is actually sitting on a glass table covered with an off-white colored cloth.  Beneath the table are 3 low powered lights to evenly disperse the light.  There is a cardboard cutout of a female figure taped to the bottom of the table beneath the cloth.  The effect is that of a shadow puppet.<br/><br/>The image was shot from above, using a black leather jacket for the background.  There are a few bright spotlights from above to help diffuse unwanted shadows and balance the light coming from beneath the table.  There was a yellow-shaded spotlight from the back, which resulted in the bottle shadow in the foreground.  The critics are still deciding whether or not it distracts from the photo... I did it on purpose to add a little extra confusion and give an effect of multiple lighting angles.<br/><br/>This was an extremely fun photo to set up.  By far, its the most complex photo I''ve ever made in a staged setting.  It took about 50 shots to get it right and I experimented with 3 completely different setups.   The biggest challenge was making sure the lights beneath the table didn''t blead through the white cloth causing a washout, which looked horrible.<br/></td>', 'Thanks for all the comments... kept me entertained during the voting week.This image was recommended for disqualification.  Good thing I had the original with EXIF data available ;)  Thanks to those that recommended it... I enjoy being kept on my toes.Here''s how it was done... the bottle is actually sitting on a glass table covered with an off-white colored cloth.  Beneath the table are 3 low powered lights to evenly disperse the light.  There is a cardboard cutout of a female figure taped to the bottom of the table beneath the cloth.  The effect is that of a shadow puppet.The image was shot from above, using a black leather jacket for the background.  There are a few bright spotlights from above to help diffuse unwanted shadows and balance the light coming from beneath the table.  There was a yellow-shaded spotlight from the back, which resulted in the bottle shadow in the foreground.  The critics are still deciding whether or not it distracts from the photo... I did it on purpose to add a little extra confusion and give an effect of multiple lighting angles.This was an extremely fun photo to set up.  By far, its the most complex photo I''ve ever made in a staged setting.  It took about 50 shots to get it right and I experimented with 3 completely different setups.   The biggest challenge was making sure the lights beneath the table didn''t blead through the white cloth causing a washout, which looked horrible.', '2002-06-24 20:42:00.000000', NULL, 0),
(73742, 2448, 1877, '<td valign="top">Wow.. I''m impressed!! And now I wanna copy and see if I can do it/something simliar with my camera. Very inspiring  and creative!</td>', 'Wow.. I''m impressed!! And now I wanna copy and see if I can do it/something simliar with my camera. Very inspiring  and creative!', '2002-06-25 00:41:00.000000', NULL, 0),
(73743, 2448, 47, '<td valign="top">i cant believe how many people didnt know how this was done. wish you did better.</td>', 'i cant believe how many people didnt know how this was done. wish you did better.', '2002-06-25 20:32:00.000000', NULL, 0),
(73744, 2448, 3402, '<td valign="top">wow.  this is a great idea.  good job.  you should have done better.</td>', 'wow.  this is a great idea.  good job.  you should have done better.', '2002-08-23 02:25:00.000000', NULL, 0),
