(74008, 2458, 570, '<td valign="top">WHAT?</td>', 'WHAT?', '2002-06-20 16:51:00.000000', NULL, 1),
(74009, 2458, 1005, '<td valign="top">It took me three separate viewings to "get" this shot.  It''s wonderful, if a bit subtle.  As a "shot of opportunity", this is extremely good.  It wasn''t until I tried to figure out what the flash reflection was, that I spotted the bumble bee.  Originally gave you a 7, it''s a clear shot, etc. etc., but the bee''s shadow is the "bee''s knees".  I had considered this, in natural light, but didn''t like the definition I was getting.  I can see his shadowy legs!  VERY, VERY good.  I don''t get the orange strip on the right side, and it really grabs my attention away from the subject.  This appears to be from a fairly high end camera, so you might have some extra resolution to play with.  Did you try cropping down to about the middle 1/3?  Just a thought....<br/>Photo 9 Creativity 9 Shadows 9 total 9</td>', 'It took me three separate viewings to "get" this shot.  It''s wonderful, if a bit subtle.  As a "shot of opportunity", this is extremely good.  It wasn''t until I tried to figure out what the flash reflection was, that I spotted the bumble bee.  Originally gave you a 7, it''s a clear shot, etc. etc., but the bee''s shadow is the "bee''s knees".  I had considered this, in natural light, but didn''t like the definition I was getting.  I can see his shadowy legs!  VERY, VERY good.  I don''t get the orange strip on the right side, and it really grabs my attention away from the subject.  This appears to be from a fairly high end camera, so you might have some extra resolution to play with.  Did you try cropping down to about the middle 1/3?  Just a thought....Photo 9 Creativity 9 Shadows 9 total 9', '2002-06-21 13:55:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(74010, 2458, 811, '<td valign="top">Just for the record, I saw the bee before you posted in the forums, I just hadn''t gotten around to commenting yet.  An no, it doesn''t bother me that I "know" who took the picture, my comment will be the same.<br/>I found the picture to be hilarious, and figured that he was trying to get "in" the orange thing.  However, the orange thing is so bright and the rest is so "natural'' that the  eye automatically goes to that side.    As far as the bumblebee goes, those are hard little suckers to photograph!  Good job.</td>', 'Just for the record, I saw the bee before you posted in the forums, I just hadn''t gotten around to commenting yet.  An no, it doesn''t bother me that I "know" who took the picture, my comment will be the same.I found the picture to be hilarious, and figured that he was trying to get "in" the orange thing.  However, the orange thing is so bright and the rest is so "natural'' that the  eye automatically goes to that side.    As far as the bumblebee goes, those are hard little suckers to photograph!  Good job.', '2002-06-21 18:47:00.000000', NULL, 1),
(74011, 2458, 1175, '<td valign="top">You definitely got a picture of a shadow here, a few actually, but there is too much going on in this photo.  Capture of the bee is good but for it to be interesting you have to get real close... without getting stung. :)</td>', 'You definitely got a picture of a shadow here, a few actually, but there is too much going on in this photo.  Capture of the bee is good but for it to be interesting you have to get real close... without getting stung. :)', '2002-06-22 12:56:00.000000', NULL, 1),
(74012, 2458, 1, '<td valign="top">I think a tighter crop on the bee and his shadow could''ve made this much better</td>', 'I think a tighter crop on the bee and his shadow could''ve made this much better', '2002-06-23 20:07:00.000000', NULL, 1),
(74013, 2458, 2217, '<td valign="top">taking a look at your picture a second time, it is a very good picture, I was perhaps too critical during the voting.  Your focusing is excellent.  I agree with what jmsetzler says about your picture.  You did deserve a higher score.  I should have also given you a better score.  Better luck next time.</td>', 'taking a look at your picture a second time, it is a very good picture, I was perhaps too critical during the voting.  Your focusing is excellent.  I agree with what jmsetzler says about your picture.  You did deserve a higher score.  I should have also given you a better score.  Better luck next time.', '2002-06-27 13:06:00.000000', NULL, 0),
(74014, 2458, 2111, '<td valign="top">Jean, thanks for ur comment. I tried cropping just into the bee but it was too pixlated and I thought the orange reflector of the telephone pole would ass to it because it was in a honecomb shape. the other parts of the picture just seemed to difuse the brightness of the reflector and add more shadows...but instead it distracted from the bee. I tried to change my title to "Bee My Shadow" <br/>Mags</td>', 'Jean, thanks for ur comment. I tried cropping just into the bee but it was too pixlated and I thought the orange reflector of the telephone pole would ass to it because it was in a honecomb shape. the other parts of the picture just seemed to difuse the brightness of the reflector and add more shadows...but instead it distracted from the bee. I tried to change my title to "Bee My Shadow" Mags', '2002-07-04 08:39:00.000000', NULL, 0),
(74015, 2459, 593, '<td valign="top">Interesting!</td>', 'Interesting!', '2002-06-17 02:21:00.000000', NULL, 1),
(74016, 2459, 1856, '<td valign="top">one of my favorites...great photo!</td>', 'one of my favorites...great photo!', '2002-06-17 12:11:00.000000', NULL, 1),
(74017, 2459, 327, '<td valign="top">Of course now I''ll have that song in my head all day! &amp;lt;g&amp;gt; Cute idea for your shot and done well.</td>', 'Of course now I''ll have that song in my head all day! &lt;g&gt; Cute idea for your shot and done well.', '2002-06-17 15:26:00.000000', NULL, 1),
(74018, 2459, 570, '<td valign="top">she has the whitest teeth I ever came upon.</td>', 'she has the whitest teeth I ever came upon.', '2002-06-17 16:18:00.000000', NULL, 1),
(74019, 2459, 1293, '<td valign="top">HOT! The sun looks so hot.</td>', 'HOT! The sun looks so hot.', '2002-06-17 16:47:00.000000', NULL, 1),
(74020, 2459, 1005, '<td valign="top">Well executed Black and White (hey, wasn''t that last week?)  Did color "look" bad?  Excellent focus.  I wish I liked B&amp;W better.  This is very good. <br/>(But, I don''t, sorry!)  Photo 8 Creativity 5 Shadows 6 total 7</td>', 'Well executed Black and White (hey, wasn''t that last week?)  Did color "look" bad?  Excellent focus.  I wish I liked B&W better.  This is very good. (But, I don''t, sorry!)  Photo 8 Creativity 5 Shadows 6 total 7', '2002-06-17 19:13:00.000000', NULL, 1),
(74021, 2459, 1009, '<td valign="top">Nice job...</td>', 'Nice job...', '2002-06-17 19:55:00.000000', NULL, 1),
(74022, 2459, 1607, '<td valign="top">Wrapped up like a deuce?</td>', 'Wrapped up like a deuce?', '2002-06-17 20:04:00.000000', NULL, 1),
(74023, 2459, 1563, '<td valign="top">Beautiful girl, nice shadow picture.  Good job.</td>', 'Beautiful girl, nice shadow picture.  Good job.', '2002-06-17 20:53:00.000000', NULL, 1),
(74024, 2459, 1585, '<td valign="top">O.K. This is cool. Nice crisp, distinct shadow.</td>', 'O.K. This is cool. Nice crisp, distinct shadow.', '2002-06-17 22:45:00.000000', NULL, 1),
(74025, 2459, 1666, '<td valign="top">A pretty model always makes a nice photo, even with a hand over her face :) I find the shadow on the ground behind her, and under her arm, a bit distracting.</td>', 'A pretty model always makes a nice photo, even with a hand over her face :) I find the shadow on the ground behind her, and under her arm, a bit distracting.', '2002-06-18 00:23:00.000000', NULL, 1),
(74026, 2459, 1599, '<td valign="top">OK</td>', 'OK', '2002-06-18 02:28:00.000000', NULL, 1),
(74027, 2459, 1882, '<td valign="top">nice</td>', 'nice', '2002-06-18 10:34:00.000000', NULL, 1),
(74028, 2459, 1041, '<td valign="top">Great idea for shadow.  Works well in b&amp;w.  Good focus, and I like that the hand is only partially visible.  I wish her left eye was totally in the sun, but that''s just a nitpick.  In my top 3 this week!</td>', 'Great idea for shadow.  Works well in b&w.  Good focus, and I like that the hand is only partially visible.  I wish her left eye was totally in the sun, but that''s just a nitpick.  In my top 3 this week!', '2002-06-18 17:23:00.000000', NULL, 1),
(74029, 2459, 1054, '<td valign="top">Very good composition, and a pretty lady too.</td>', 'Very good composition, and a pretty lady too.', '2002-06-18 18:17:00.000000', NULL, 1),
(74030, 2459, 554, '<td valign="top">good seperation of light and dark and dof</td>', 'good seperation of light and dark and dof', '2002-06-18 23:47:00.000000', NULL, 1),
(74031, 2459, 1793, '<td valign="top">i feel like the eye she didn''t cover is being blinded :D</td>', 'i feel like the eye she didn''t cover is being blinded :D', '2002-06-19 03:12:00.000000', NULL, 1),
(74032, 2459, 2173, '<td valign="top">i like the hands...and the girl its cute.......</td>', 'i like the hands...and the girl its cute.......', '2002-06-19 12:46:00.000000', NULL, 1),
(74033, 2459, 2328, '<td valign="top">Great view point and a nice idea.<br/></td>', 'Great view point and a nice idea.', '2002-06-20 16:03:00.000000', NULL, 1),
(74034, 2459, 2152, '<td valign="top">I like this shot, but I think it would look better without the shadows on the right side of the pic by her shoulder and arm.  Also, it looks a little strange with just half the hand in the frame.  But overall it''s nice.</td>', 'I like this shot, but I think it would look better without the shadows on the right side of the pic by her shoulder and arm.  Also, it looks a little strange with just half the hand in the frame.  But overall it''s nice.', '2002-06-20 16:35:00.000000', NULL, 1),
(74035, 2459, 772, '<td valign="top">good shot... i like the hand shadow.. :) - jmsetzler</td>', 'good shot... i like the hand shadow.. :) - jmsetzler', '2002-06-20 18:05:00.000000', NULL, 1),
(74036, 2459, 2346, '<td valign="top">The picture is pretty good, but it looks too staged!</td>', 'The picture is pretty good, but it looks too staged!', '2002-06-21 20:03:00.000000', NULL, 1),
(74037, 2459, 1, '<td valign="top">Nice idea, I''d prefer a little more DOF to have her hand in focus as well.  Those are some white teeth.</td>', 'Nice idea, I''d prefer a little more DOF to have her hand in focus as well.  Those are some white teeth.', '2002-06-23 17:24:00.000000', NULL, 1),
(74038, 2460, 741, '<td valign="top">Focusing needs to be a little sharepr on the reels for this to work</td>', 'Focusing needs to be a little sharepr on the reels for this to work', '2002-06-17 13:46:00.000000', NULL, 1),
(74039, 2460, 436, '<td valign="top">love the color and simplicity! Nice crisp shadow and great wall!</td>', 'love the color and simplicity! Nice crisp shadow and great wall!', '2002-06-17 13:52:00.000000', NULL, 1),
(74040, 2460, 2243, '<td valign="top">I like this!</td>', 'I like this!', '2002-06-17 14:20:00.000000', NULL, 1),
(74041, 2460, 1944, '<td valign="top">I like the your use of color. One thing I might have done is to control exposure so that the light side of the threads weren''t blown out so much.</td>', 'I like the your use of color. One thing I might have done is to control exposure so that the light side of the threads weren''t blown out so much.', '2002-06-17 15:22:00.000000', NULL, 1),
(74042, 2460, 1031, '<td valign="top">I like your choice of a defined multi-color subject.</td>', 'I like your choice of a defined multi-color subject.', '2002-06-17 15:33:00.000000', NULL, 1),
(74043, 2460, 327, '<td valign="top">Nice. Little over exposed but pretty good.</td>', 'Nice. Little over exposed but pretty good.', '2002-06-17 16:15:00.000000', NULL, 1),
(74044, 2460, 2123, '<td valign="top">Great color, crisp shadows...I love this shot!</td>', 'Great color, crisp shadows...I love this shot!', '2002-06-17 19:34:00.000000', NULL, 1),
(74045, 2460, 1856, '<td valign="top">great colors, crisp shadow, nice focus/detail.  my only suggestion for improvement is ridiculous...since the surface the spools are sitting on looks weathered/antiquish, the image might look more ''tied-together'' (suffering from T.O.T.) if the spools were wooden.</td>', 'great colors, crisp shadow, nice focus/detail.  my only suggestion for improvement is ridiculous...since the surface the spools are sitting on looks weathered/antiquish, the image might look more ''tied-together'' (suffering from T.O.T.) if the spools were wooden.', '2002-06-17 20:08:00.000000', NULL, 1),
(74046, 2460, 2153, '<td valign="top">Beautiful. AND Crisp! Nice job.</td>', 'Beautiful. AND Crisp! Nice job.', '2002-06-17 23:39:00.000000', NULL, 1),
(74047, 2460, 1599, '<td valign="top">COTTON REELS?   I don''t like.</td>', 'COTTON REELS?   I don''t like.', '2002-06-18 02:15:00.000000', NULL, 1),
(74048, 2460, 2235, '<td valign="top">Good shot!! Nice idea with common household items. Dark shadows really fit the title theme well.  One of the best.</td>', 'Good shot!! Nice idea with common household items. Dark shadows really fit the title theme well.  One of the best.', '2002-06-18 10:35:00.000000', NULL, 1),
(74049, 2460, 1882, '<td valign="top">nicely done</td>', 'nicely done', '2002-06-18 10:38:00.000000', NULL, 1),
(74050, 2460, 1759, '<td valign="top">I like this photo because of it''s simplicity, composition, and pleasant combination of soft color. It takes a good eye to find such a jewel in common simple items. I also like the way you broke up the background by using black on the right to created a balance with the shadow on the left. There is a slight problem with lighting harshness that robs from the soft texture by blowing out some highlights. Since there is plenty of contrast, I think that this could have been lessened or avoided altogether with a change of f-stop or shutter speed, or by using a polarizer or neutral density filter.</td>', 'I like this photo because of it''s simplicity, composition, and pleasant combination of soft color. It takes a good eye to find such a jewel in common simple items. I also like the way you broke up the background by using black on the right to created a balance with the shadow on the left. There is a slight problem with lighting harshness that robs from the soft texture by blowing out some highlights. Since there is plenty of contrast, I think that this could have been lessened or avoided altogether with a change of f-stop or shutter speed, or by using a polarizer or neutral density filter.', '2002-06-18 17:51:00.000000', NULL, 1),
(74051, 2460, 1054, '<td valign="top">Good framing and lighting.</td>', 'Good framing and lighting.', '2002-06-18 18:03:00.000000', NULL, 1),
(74052, 2460, 92, '<td valign="top">This is a really neat photo ! I like the textures and color. The shadow is just awesome. The only flaw I can see is the light over exposure on the thread in places.</td>', 'This is a really neat photo ! I like the textures and color. The shadow is just awesome. The only flaw I can see is the light over exposure on the thread in places.', '2002-06-18 22:44:00.000000', NULL, 1),
(74053, 2460, 811, '<td valign="top">I like the way you have set this up.  Did you try it with different colors of spools.  I have found that if you include red in a picture, it seems to make it stand out more.  This might also make a nice black and white shot.</td>', 'I like the way you have set this up.  Did you try it with different colors of spools.  I have found that if you include red in a picture, it seems to make it stand out more.  This might also make a nice black and white shot.', '2002-06-20 01:09:00.000000', NULL, 1),
(74054, 2460, 772, '<td valign="top">This is quite nice!  I love this concept... I wonder what this would look like with a RED spool in the stack :)  good work! - jmsetzler</td>', 'This is quite nice!  I love this concept... I wonder what this would look like with a RED spool in the stack :)  good work! - jmsetzler', '2002-06-21 01:08:00.000000', NULL, 1),
(74055, 2460, 1005, '<td valign="top">This has to be the clearest, most defined shadows in the challenge.  The threads trailing off are a very nice touch.  Second viewing bumps you up a point.  This is really nice.  Photo 9 Creativity 9 Shadows 10 Total 9</td>', 'This has to be the clearest, most defined shadows in the challenge.  The threads trailing off are a very nice touch.  Second viewing bumps you up a point.  This is really nice.  Photo 9 Creativity 9 Shadows 10 Total 9', '2002-06-21 14:15:00.000000', NULL, 1),
(74056, 2460, 641, '<td valign="top">I love the variety of colors and the warmth in this.</td>', 'I love the variety of colors and the warmth in this.', '2002-06-21 15:59:00.000000', NULL, 1),
(74057, 2460, 1, '<td valign="top">Nicely shot and composed.</td>', 'Nicely shot and composed.', '2002-06-22 12:45:00.000000', NULL, 1),
(74058, 2460, 715, '<td valign="top">Nice colorfull photo. I think you should have cropped/framed it tighter though, to get rid of both the shelf and the blue background to the left and top of the shadow.</td>', 'Nice colorfull photo. I think you should have cropped/framed it tighter though, to get rid of both the shelf and the blue background to the left and top of the shadow.', '2002-06-23 16:44:00.000000', NULL, 1),
(74059, 2461, 1175, '<td valign="top">Nice colors.  Very abstract.  I like it.  For this challenge though I would have liked to been able to tell what I was looking at.</td>', 'Nice colors.  Very abstract.  I like it.  For this challenge though I would have liked to been able to tell what I was looking at.', '2002-06-17 12:51:00.000000', NULL, 1),
(74060, 2461, 1005, '<td valign="top">????? Nice shadows, but the title?  I don''t get it.  Interesting shadows...I just realized there are two walls coming together (I was going to complain that half the photo appeared out of focus, but now I get it.)  Photo 6 Creativity 5 Shadows 7 total 6</td>', '????? Nice shadows, but the title?  I don''t get it.  Interesting shadows...I just realized there are two walls coming together (I was going to complain that half the photo appeared out of focus, but now I get it.)  Photo 6 Creativity 5 Shadows 7 total 6', '2002-06-17 14:29:00.000000', NULL, 1),
(74061, 2461, 1944, '<td valign="top">I like the graphic design of your photo very much. The color, composition, textural elements work in harmony to create a very nice picture.</td>', 'I like the graphic design of your photo very much. The color, composition, textural elements work in harmony to create a very nice picture.', '2002-06-17 22:05:00.000000', NULL, 1),
(74062, 2461, 1856, '<td valign="top">I can''t wait to see the explanation of this...is the redman made by the shadows of a sheer fabric or tropical plant?  Good eye.</td>', 'I can''t wait to see the explanation of this...is the redman made by the shadows of a sheer fabric or tropical plant?  Good eye.', '2002-06-17 23:45:00.000000', NULL, 1),
(74063, 2461, 1599, '<td valign="top">Where is the tree.</td>', 'Where is the tree.', '2002-06-18 02:29:00.000000', NULL, 1),
(74064, 2461, 1041, '<td valign="top">Ok, so this may be a really wild off the mark guess, but is this an umbrella?  You got me intrigued.</td>', 'Ok, so this may be a really wild off the mark guess, but is this an umbrella?  You got me intrigued.', '2002-06-18 10:42:00.000000', NULL, 1),
(74065, 2461, 1054, '<td valign="top">Very abstract.  I''m not sure what the soft-focus accomplishes, though.</td>', 'Very abstract.  I''m not sure what the soft-focus accomplishes, though.', '2002-06-18 11:54:00.000000', NULL, 1),
(74066, 2461, 2094, '<td valign="top">Pretty red colors, and interesting shadow patterns. I''m not quite sure what I think of the wall texture, though...</td>', 'Pretty red colors, and interesting shadow patterns. I''m not quite sure what I think of the wall texture, though...', '2002-06-18 12:21:00.000000', NULL, 1),
(74067, 2461, 1759, '<td valign="top">Good job, visually Interesting shapes with a nice background hue. I''m not so sure about the two-tone background texture though, I think it might be better with just the more solid panel used on the right side of the photo.</td>', 'Good job, visually Interesting shapes with a nice background hue. I''m not so sure about the two-tone background texture though, I think it might be better with just the more solid panel used on the right side of the photo.', '2002-06-18 14:02:00.000000', NULL, 1),
(74068, 2461, 1831, '<td valign="top">Very clever, Had to look twice but found his face in top left. I''d be interested to know how many PPL miss this one. "8" for creativity. Dogman :-)<br/>PS: Do you think it looks like Mr Burns out of the Simpsons?</td>', 'Very clever, Had to look twice but found his face in top left. I''d be interested to know how many PPL miss this one. "8" for creativity. Dogman :-)PS: Do you think it looks like Mr Burns out of the Simpsons?', '2002-06-18 16:36:00.000000', NULL, 1),
(74069, 2461, 527, '<td valign="top">I think it''s a little too abstract.</td>', 'I think it''s a little too abstract.', '2002-06-19 01:02:00.000000', NULL, 1),
(74070, 2461, 1783, '<td valign="top">Soothing picture.</td>', 'Soothing picture.', '2002-06-19 10:30:00.000000', NULL, 1),
(74071, 2461, 693, '<td valign="top">I see this... the eyes, the nose and the chin.</td>', 'I see this... the eyes, the nose and the chin.', '2002-06-19 12:33:00.000000', NULL, 1),
(74072, 2461, 772, '<td valign="top">I like the abstract aspects of this photo... the facial outline in this image is neat :) Looks like a huge nose :)  Nice work! - jmsetzler</td>', 'I like the abstract aspects of this photo... the facial outline in this image is neat :) Looks like a huge nose :)  Nice work! - jmsetzler', '2002-06-19 14:53:00.000000', NULL, 1),
(74073, 2461, 205, '<td valign="top">I wonder if you tried to make a face or you saw it than titled it in that way to bring it our attention. Whatever you did you got a ten.</td>', 'I wonder if you tried to make a face or you saw it than titled it in that way to bring it our attention. Whatever you did you got a ten.', '2002-06-20 09:23:00.000000', NULL, 1),
(74074, 2461, 2111, '<td valign="top">Magnifique! (6)</td>', 'Magnifique! (6)', '2002-06-22 12:53:00.000000', NULL, 1),
