(74076, 2461, 1, '<td valign="top">Very nice looking, the colors are superb.</td>', 'Very nice looking, the colors are superb.', '2002-06-23 23:14:00.000000', NULL, 1),
(74077, 2462, 1054, '<td valign="top">Very cute! I wish the edges were sharper.</td>', 'Very cute! I wish the edges were sharper.', '2002-06-17 01:22:00.000000', NULL, 1),
(74078, 2462, 2075, '<td valign="top">Interesting shadow for sure! And there''s nothing wrong with simple shadows, but, to me, this is a bit too simple.</td>', 'Interesting shadow for sure! And there''s nothing wrong with simple shadows, but, to me, this is a bit too simple.', '2002-06-17 01:22:00.000000', NULL, 1),
