(74080, 2462, 1031, '<td valign="top">Hey, I have a couple of shots where the mask has more than one hole -- I didn''t recognize those weird eyes! Now I''ll have to go back and look for "hidden bugs" in those photos.</td>', 'Hey, I have a couple of shots where the mask has more than one hole -- I didn''t recognize those weird eyes! Now I''ll have to go back and look for "hidden bugs" in those photos.', '2002-06-17 01:40:00.000000', NULL, 1),
(74081, 2462, 142, '<td valign="top">Neat!</td>', 'Neat!', '2002-06-17 12:39:00.000000', NULL, 1),
(74082, 2462, 1944, '<td valign="top">a fun idea.</td>', 'a fun idea.', '2002-06-17 15:23:00.000000', NULL, 1),
(74083, 2462, 2263, '<td valign="top">AWESOME!!!!!!!! The other day I almost went outside with my binoculars to do this, but I forgot.  Very clever use of light.</td>', 'AWESOME!!!!!!!! The other day I almost went outside with my binoculars to do this, but I forgot.  Very clever use of light.', '2002-06-17 16:48:00.000000', NULL, 1),
