(74370, 2491, 1569, '<td valign="top">Nice colors. The very center of the flower should be in focus as well as the petals.</td>', 'Nice colors. The very center of the flower should be in focus as well as the petals.', '2002-06-18 20:40:00.000000', NULL, 1),
(74371, 2491, 2221, '<td valign="top">whoa! what a saturation! can''t see any shadows though ;-)<br/>the picture looks a bit "pixelized" either because of a low resolution or bad jpeg quality.</td>', 'whoa! what a saturation! can''t see any shadows though ;-)the picture looks a bit "pixelized" either because of a low resolution or bad jpeg quality.', '2002-06-19 09:21:00.000000', NULL, 1),
