(74393, 2495, 2221, '<td valign="top">the nose looks funny because of the shadow ;-) the head is a little bit too far on the right but i like it though. nice lighting.</td>', 'the nose looks funny because of the shadow ;-) the head is a little bit too far on the right but i like it though. nice lighting.', '2002-06-19 09:04:00.000000', NULL, 1),
(74394, 2495, 1882, '<td valign="top">Man, that is creepy!  But what a great shot!  Excellent use of shadows.  Very ominous.</td>', 'Man, that is creepy!  But what a great shot!  Excellent use of shadows.  Very ominous.', '2002-06-19 13:03:00.000000', NULL, 1),
