(74396, 2495, 142, '<td valign="top">Cool photo!</td>', 'Cool photo!', '2002-06-19 18:26:00.000000', NULL, 1),
(74397, 2495, 1005, '<td valign="top">Strong photo, the nose shadow kinda make it look like it has a pig nose, but offers a dramatic effect.  Very nice!<br/>Photo 10 Creativity 8 Shadows 9 total 9</td>', 'Strong photo, the nose shadow kinda make it look like it has a pig nose, but offers a dramatic effect.  Very nice!Photo 10 Creativity 8 Shadows 9 total 9', '2002-06-19 20:59:00.000000', NULL, 1),
(74398, 2495, 1, '<td valign="top">I hope that''s not a "realdoll" ..  Why did you choose to have the light source coming up?  It gives her a pig nose.  Try a diff angle maybe.</td>', 'I hope that''s not a "realdoll" ..  Why did you choose to have the light source coming up?  It gives her a pig nose.  Try a diff angle maybe.', '2002-06-23 19:18:00.000000', NULL, 1),
(74399, 2495, 2158, '<td valign="top">I didn''t choose the light source coming up, this is how I found her in a shop window.</td>', 'I didn''t choose the light source coming up, this is how I found her in a shop window.', '2002-06-24 19:59:00.000000', NULL, 0),
