INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(74410, 2496, 327, '<td valign="top">Nice job, great color.</td>', 'Nice job, great color.', '2002-06-17 16:55:00.000000', NULL, 1),
(74411, 2496, 2172, '<td valign="top">Nice - just can''t stare at it too long</td>', 'Nice - just can''t stare at it too long', '2002-06-17 16:56:00.000000', NULL, 1),
(74412, 2496, 441, '<td valign="top">good contrast,colour and shadow</td>', 'good contrast,colour and shadow', '2002-06-17 18:24:00.000000', NULL, 1),
(74413, 2496, 1313, '<td valign="top">Good pic, nice crisp shadows.</td>', 'Good pic, nice crisp shadows.', '2002-06-17 19:02:00.000000', NULL, 1),
(74414, 2496, 737, '<td valign="top">Crystal clear! Great selection for background color.</td>', 'Crystal clear! Great selection for background color.', '2002-06-17 19:43:00.000000', NULL, 1),
(74415, 2496, 1009, '<td valign="top">Cool photo... good job</td>', 'Cool photo... good job', '2002-06-17 20:01:00.000000', NULL, 1),
(74416, 2496, 2199, '<td valign="top">Nice design....the contrast almost hurts my eyes, but I like the effect very much.</td>', 'Nice design....the contrast almost hurts my eyes, but I like the effect very much.', '2002-06-17 20:20:00.000000', NULL, 1),
(74417, 2496, 1759, '<td valign="top">I love the red wall and the shadows on it have a lot of potential. I think that having the fence in the photo detracts from the shot.</td>', 'I love the red wall and the shadows on it have a lot of potential. I think that having the fence in the photo detracts from the shot.', '2002-06-17 20:49:00.000000', NULL, 1),
(74418, 2496, 1599, '<td valign="top">How Cool.  Very interesting technique.  I like all that RED.  I hope you are not  jmsetzler.</td>', 'How Cool.  Very interesting technique.  I like all that RED.  I hope you are not  jmsetzler.', '2002-06-18 01:10:00.000000', NULL, 1),
(74419, 2496, 2094, '<td valign="top">Wow, sweet color and contrasts...</td>', 'Wow, sweet color and contrasts...', '2002-06-18 01:11:00.000000', NULL, 1),
(74420, 2496, 1224, '<td valign="top">woah spiderman</td>', 'woah spiderman', '2002-06-18 14:40:00.000000', NULL, 1),
(74421, 2496, 1041, '<td valign="top">I love the bright colors, the contrast.  And all that w/out the fence looking blown out - perfect.  Great combination of patterns, too.  In my top 10 this week.</td>', 'I love the bright colors, the contrast.  And all that w/out the fence looking blown out - perfect.  Great combination of patterns, too.  In my top 10 this week.', '2002-06-18 17:25:00.000000', NULL, 1),
(74422, 2496, 1585, '<td valign="top">Way cool. This will do very well. I''d put cold hard cash on it.</td>', 'Way cool. This will do very well. I''d put cold hard cash on it.', '2002-06-18 21:48:00.000000', NULL, 1),
(74423, 2496, 1651, '<td valign="top">...Love the red.</td>', '...Love the red.', '2002-06-18 22:11:00.000000', NULL, 1),
(74424, 2496, 92, '<td valign="top">This is a REALLY great idea. The crop, color and shadows are GREAT !</td>', 'This is a REALLY great idea. The crop, color and shadows are GREAT !', '2002-06-18 22:40:00.000000', NULL, 1),
(74425, 2496, 1793, '<td valign="top">tennis court that''s red? :) links seem to make a great abstraction though!</td>', 'tennis court that''s red? :) links seem to make a great abstraction though!', '2002-06-19 03:03:00.000000', NULL, 1),
(74426, 2496, 1037, '<td valign="top">The colours here are very vivid, and the texture of the metal stands out nicely. The shadow is almost reptillian, very cool. I think I''d like a different camera angle or something though, because the flatness of it doesn''t work for me. The lines of the fence converge a little bit towards the bottom left hand corner, I think I''d like that to have been stronger.</td>', 'The colours here are very vivid, and the texture of the metal stands out nicely. The shadow is almost reptillian, very cool. I think I''d like a different camera angle or something though, because the flatness of it doesn''t work for me. The lines of the fence converge a little bit towards the bottom left hand corner, I think I''d like that to have been stronger.', '2002-06-19 04:18:00.000000', NULL, 1),
(74427, 2496, 1783, '<td valign="top">Very simple, very nice.  I like the contrast between the red black and white.</td>', 'Very simple, very nice.  I like the contrast between the red black and white.', '2002-06-19 09:25:00.000000', NULL, 1),
(74428, 2496, 2188, '<td valign="top">I like the strong angle juxtaposition.</td>', 'I like the strong angle juxtaposition.', '2002-06-19 10:00:00.000000', NULL, 1),
(74429, 2496, 693, '<td valign="top">I like the creativity here; however, this image appears to be overly sharpened as evident by the graininess. Or perhaps an ISO of 400 or more was used.</td>', 'I like the creativity here; however, this image appears to be overly sharpened as evident by the graininess. Or perhaps an ISO of 400 or more was used.', '2002-06-19 12:24:00.000000', NULL, 1),
(74430, 2496, 2312, '<td valign="top">Nice patterns in this photo.</td>', 'Nice patterns in this photo.', '2002-06-19 15:41:00.000000', NULL, 1),
(74431, 2496, 715, '<td valign="top">Clear, simple, great color and excellent framing. One of my favorites!</td>', 'Clear, simple, great color and excellent framing. One of my favorites!', '2002-06-19 15:50:00.000000', NULL, 1),
(74432, 2496, 1882, '<td valign="top">Wow.  very cool.  Not sure how you got the red tones behind the fence, but I''m impressed.  Simple subject yet cleverly shot.</td>', 'Wow.  very cool.  Not sure how you got the red tones behind the fence, but I''m impressed.  Simple subject yet cleverly shot.', '2002-06-19 15:50:00.000000', NULL, 1),
(74433, 2496, 933, '<td valign="top">I very much like the contrast of the fence against the colors of the red and shadowed wall(?).  Very neat, interesting shot, very crisp.  Well done!</td>', 'I very much like the contrast of the fence against the colors of the red and shadowed wall(?).  Very neat, interesting shot, very crisp.  Well done!', '2002-06-19 17:04:00.000000', NULL, 1),
(74434, 2496, 1005, '<td valign="top">Powerful colors!  This makes for interesting patterns, but a bit tedious.  (Try a dandelion flower or the like in one of the links, as an idea)  <br/>Photo 8 Creativity 6 Shadows 6 total 6</td>', 'Powerful colors!  This makes for interesting patterns, but a bit tedious.  (Try a dandelion flower or the like in one of the links, as an idea)  Photo 8 Creativity 6 Shadows 6 total 6', '2002-06-19 18:37:00.000000', NULL, 1),
(74435, 2496, 811, '<td valign="top">The red really makes this picture jump out and grab you!  I really like it.  It is focused really well and has nicely contrasting colors.</td>', 'The red really makes this picture jump out and grab you!  I really like it.  It is focused really well and has nicely contrasting colors.', '2002-06-20 01:05:00.000000', NULL, 1),
(74436, 2496, 1330, '<td valign="top">Shadows and colors really good but my eyes are first drawn to the links themselves</td>', 'Shadows and colors really good but my eyes are first drawn to the links themselves', '2002-06-20 10:17:00.000000', NULL, 1),
(74437, 2496, 772, '<td valign="top">this is one of the most powerful color contrast photos I have seen this week... great shot! - jmsetzler</td>', 'this is one of the most powerful color contrast photos I have seen this week... great shot! - jmsetzler', '2002-06-20 18:10:00.000000', NULL, 1),
(74438, 2496, 875, '<td valign="top">Terrific use of color and lines.  Nicely done.</td>', 'Terrific use of color and lines.  Nicely done.', '2002-06-20 19:46:00.000000', NULL, 1),
(74439, 2496, 318, '<td valign="top">Excellent pattern. Wallpaper material</td>', 'Excellent pattern. Wallpaper material', '2002-06-21 13:05:00.000000', NULL, 1),
(74440, 2496, 2126, '<td valign="top">I like the pattern - very nice, but a bit bright if (like me) you are colour blind</td>', 'I like the pattern - very nice, but a bit bright if (like me) you are colour blind', '2002-06-21 13:37:00.000000', NULL, 1),
(74441, 2496, 641, '<td valign="top">I like how the shadows are opposite of the links and the red really is great.</td>', 'I like how the shadows are opposite of the links and the red really is great.', '2002-06-21 17:15:00.000000', NULL, 1),
(74442, 2496, 2111, '<td valign="top">I cant tell if I rated this picture high because it stands out from the rest or because its done very well with the shadows. (7)</td>', 'I cant tell if I rated this picture high because it stands out from the rest or because its done very well with the shadows. (7)', '2002-06-22 11:11:00.000000', NULL, 1),
(74443, 2496, 637, '<td valign="top">love the colors and the perspective.</td>', 'love the colors and the perspective.', '2002-06-23 02:20:00.000000', NULL, 1),
(74444, 2496, 1, '<td valign="top">Awesome contrast... very well done.  The red/white/black are superb.</td>', 'Awesome contrast... very well done.  The red/white/black are superb.', '2002-06-23 19:09:00.000000', NULL, 1),
(74445, 2496, 661, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2002-06-24 00:13:00.000000', NULL, 1),
(74446, 2496, 312, '<td valign="top">rediculous.</td>', 'rediculous.', '2002-06-24 01:08:00.000000', NULL, 0),
(74447, 2496, 2, '<td valign="top">Really a stunning shot -- nicely done!</td>', 'Really a stunning shot -- nicely done!', '2002-06-26 02:14:00.000000', NULL, 0),
(74448, 2499, 1944, '<td valign="top">The composition is unbalanced with the hands on the left side. Poor exposure.</td>', 'The composition is unbalanced with the hands on the left side. Poor exposure.', '2002-06-17 13:46:00.000000', NULL, 1),
(74449, 2499, 1175, '<td valign="top">Really over exposed.</td>', 'Really over exposed.', '2002-06-17 14:24:00.000000', NULL, 1),
(74450, 2499, 1313, '<td valign="top">OK, I had thought of this but did not do, needs more color though</td>', 'OK, I had thought of this but did not do, needs more color though', '2002-06-17 19:00:00.000000', NULL, 1),
(74451, 2499, 1005, '<td valign="top">(Questions:  Dead grass? Run out of color film? joke)  Hide the arms (maybe with another shadow), even up the color of the grass (too pale in foreground) and crop your own shadow (at the bottom).  A little less than really interesting, do something to create interest, reason to view again.<br/>Photo 6 Creativity 4 Shadows 7 total 6</td>', '(Questions:  Dead grass? Run out of color film? joke)  Hide the arms (maybe with another shadow), even up the color of the grass (too pale in foreground) and crop your own shadow (at the bottom).  A little less than really interesting, do something to create interest, reason to view again.Photo 6 Creativity 4 Shadows 7 total 6', '2002-06-17 20:00:00.000000', NULL, 1),
(74452, 2499, 1599, '<td valign="top">Fly Fly Fly, I still make these hand shadows too.  Should have cut out the arms part.</td>', 'Fly Fly Fly, I still make these hand shadows too.  Should have cut out the arms part.', '2002-06-18 01:07:00.000000', NULL, 1),
(74453, 2499, 1054, '<td valign="top">Nice shot, but the shadow at the bottom of the image is a distraction.</td>', 'Nice shot, but the shadow at the bottom of the image is a distraction.', '2002-06-19 06:28:00.000000', NULL, 1),
(74454, 2499, 772, '<td valign="top">Nice hand shadow... it appears that the ground is a little over exposed.. this can be a bit tricky sometimes when creating a photograph that contains light and dark areas like your submission.  It looks like your camera may have metered on the darker area and allowed more light in the lens than necessary... good shot though :) - jmsetzler</td>', 'Nice hand shadow... it appears that the ground is a little over exposed.. this can be a bit tricky sometimes when creating a photograph that contains light and dark areas like your submission.  It looks like your camera may have metered on the darker area and allowed more light in the lens than necessary... good shot though :) - jmsetzler', '2002-06-19 13:10:00.000000', NULL, 1),
(74455, 2499, 811, '<td valign="top">This is a good idea, though I think the picture could have been improved by having the bird/hands enter the picture at a different angle.  Maybe changing the position of the camera to get the bird flying in from the corner.  That may have also eliminated teh the blurb of a shadow on the bottom.</td>', 'This is a good idea, though I think the picture could have been improved by having the bird/hands enter the picture at a different angle.  Maybe changing the position of the camera to get the bird flying in from the corner.  That may have also eliminated teh the blurb of a shadow on the bottom.', '2002-06-21 15:09:00.000000', NULL, 1),
(74456, 2499, 689, '<td valign="top">Very overexposed.</td>', 'Very overexposed.', '2002-06-21 19:32:00.000000', NULL, 1),
(74457, 2500, 1054, '<td valign="top">Great capture, I love the silhouettes.</td>', 'Great capture, I love the silhouettes.', '2002-06-17 01:23:00.000000', NULL, 1),
(74458, 2500, 1344, '<td valign="top">Super pic, but more of a display of reflections than shadows</td>', 'Super pic, but more of a display of reflections than shadows', '2002-06-17 02:09:00.000000', NULL, 1),
(74459, 2500, 2251, '<td valign="top">center flower more</td>', 'center flower more', '2002-06-17 04:32:00.000000', NULL, 1),
(74460, 2500, 857, '<td valign="top">Very somber, I love it</td>', 'Very somber, I love it', '2002-06-17 16:44:00.000000', NULL, 1),
(74461, 2500, 1563, '<td valign="top">Great picture, a bit dark but a great picture, I''d give it a bit higher grade if I would see the color of the flowers a bit better.</td>', 'Great picture, a bit dark but a great picture, I''d give it a bit higher grade if I would see the color of the flowers a bit better.', '2002-06-17 17:45:00.000000', NULL, 1),
(74462, 2500, 2109, '<td valign="top">is that a pool or a hot tub through the window?</td>', 'is that a pool or a hot tub through the window?', '2002-06-17 19:01:00.000000', NULL, 1),
(74463, 2500, 1005, '<td valign="top">Very interesting shot.  This shadow challenge created some difficult photos to suggest/comment.  I think I would have liked seeing the flowers (I think they are red, maybe)  and lose the magazine, no help.  Very artsy, but dark.  Photo 7 Creativity 7 Shadows 8 total 7</td>', 'Very interesting shot.  This shadow challenge created some difficult photos to suggest/comment.  I think I would have liked seeing the flowers (I think they are red, maybe)  and lose the magazine, no help.  Very artsy, but dark.  Photo 7 Creativity 7 Shadows 8 total 7', '2002-06-17 19:25:00.000000', NULL, 1),
(74464, 2500, 2243, '<td valign="top">a little dim, but I like the effect with the blinds</td>', 'a little dim, but I like the effect with the blinds', '2002-06-17 20:07:00.000000', NULL, 1),
(74465, 2500, 1944, '<td valign="top">An excellent concept, very nicely done. I even like the sun blooming on the blinds and burning out the paper on the desk. If I were to make any suggestions at all, it would be to expose about one stop lighter, let the outside world burn some and pick up a little more detail in the flowers and the vase. If it wern''t for the restraints of the composition you could have easily done some local manipulation, it looks like there''s enough data in the shadows.</td>', 'An excellent concept, very nicely done. I even like the sun blooming on the blinds and burning out the paper on the desk. If I were to make any suggestions at all, it would be to expose about one stop lighter, let the outside world burn some and pick up a little more detail in the flowers and the vase. If it wern''t for the restraints of the composition you could have easily done some local manipulation, it looks like there''s enough data in the shadows.', '2002-06-17 21:33:00.000000', NULL, 1),
(74466, 2500, 1783, '<td valign="top">Shadows against the bright light entering the room is nice.</td>', 'Shadows against the bright light entering the room is nice.', '2002-06-19 09:22:00.000000', NULL, 1),
(74467, 2500, 811, '<td valign="top">Great use of shadows.  I think if the light on the flowers had been a little more bright, so that the red really showed, it would have been a little more effective.  I like it as it is, though.  Nice job.</td>', 'Great use of shadows.  I think if the light on the flowers had been a little more bright, so that the red really showed, it would have been a little more effective.  I like it as it is, though.  Nice job.', '2002-06-20 01:22:00.000000', NULL, 1),
