(74555, 2508, 1792, '<td valign="top">Neat photo, but doesn''t seem, to me, to capture the theme of shadows as vividly as it might have.</td>', 'Neat photo, but doesn''t seem, to me, to capture the theme of shadows as vividly as it might have.', '2002-06-18 01:09:00.000000', NULL, 1),
(74556, 2508, 1599, '<td valign="top">?</td>', '?', '2002-06-18 01:28:00.000000', NULL, 1),
(74557, 2508, 2235, '<td valign="top">To me really doesn''t fit the subject matter title. More senic shot than "shadows"<br/>Excellent shot. Well framed, exposure good and contrast works well. Just doesn''t fit theme.</td>', 'To me really doesn''t fit the subject matter title. More senic shot than "shadows"Excellent shot. Well framed, exposure good and contrast works well. Just doesn''t fit theme.', '2002-06-18 10:29:00.000000', NULL, 1),
(74558, 2508, 509, '<td valign="top">I like the grainy look of the sky and the picture overall.  Nice job.  Is that a sepia or black and white tone?  It''s difficult to tell on my moniter</td>', 'I like the grainy look of the sky and the picture overall.  Nice job.  Is that a sepia or black and white tone?  It''s difficult to tell on my moniter', '2002-06-18 15:20:00.000000', NULL, 1),
(74559, 2508, 1054, '<td valign="top">Unique interpretation, and well-done.</td>', 'Unique interpretation, and well-done.', '2002-06-18 17:44:00.000000', NULL, 1),
(74560, 2508, 1031, '<td valign="top">Too bad a lot of people probably wouldn''t get it if you''d just titled it "Psalm 23" -- I think it would tighten up the overall presentation ("verbal cropping?"), but I like your idea overall.</td>', 'Too bad a lot of people probably wouldn''t get it if you''d just titled it "Psalm 23" -- I think it would tighten up the overall presentation ("verbal cropping?"), but I like your idea overall.', '2002-06-19 02:41:00.000000', NULL, 1),
(74561, 2508, 1005, '<td valign="top">Yes, there are shadows in the bellfry, so this was the subject or point of interest in this photo?  (I just can''t stretch this far, even with the title)<br/>Photo 5 Creativity 3 Shadows 3 total 4</td>', 'Yes, there are shadows in the bellfry, so this was the subject or point of interest in this photo?  (I just can''t stretch this far, even with the title)Photo 5 Creativity 3 Shadows 3 total 4', '2002-06-19 14:13:00.000000', NULL, 1),
(74562, 2508, 205, '<td valign="top">Its neat how the strongest whites are coming from the building. I''m thinking that this is one of those pictures that would have looked way better centered. Plust it apears slightly titled<br/></td>', 'Its neat how the strongest whites are coming from the building. I''m thinking that this is one of those pictures that would have looked way better centered. Plust it apears slightly titled', '2002-06-20 09:16:00.000000', NULL, 1),
(74563, 2508, 570, '<td valign="top">no</td>', 'no', '2002-06-20 16:50:00.000000', NULL, 1),
(74564, 2508, 772, '<td valign="top">This is excellent... the *shadow* theme may be a little weak, but it''s there for sure.  I would have climbed up there and hit the bottom of that cross with some spray paint to get the bird doodie off... nice shot! = 9 - jmsetzler</td>', 'This is excellent... the *shadow* theme may be a little weak, but it''s there for sure.  I would have climbed up there and hit the bottom of that cross with some spray paint to get the bird doodie off... nice shot! = 9 - jmsetzler', '2002-06-20 20:21:00.000000', NULL, 1),
(74565, 2508, 811, '<td valign="top">I had a shot of tombstones with this same title!  Interesting compostition.</td>', 'I had a shot of tombstones with this same title!  Interesting compostition.', '2002-06-23 01:33:00.000000', NULL, 1),
(74566, 2508, 1, '<td valign="top">The shadow just isn''t the subject.</td>', 'The shadow just isn''t the subject.', '2002-06-23 19:09:00.000000', NULL, 1),
(74567, 2511, 92, '<td valign="top"><br/></td>', '', '2002-06-17 09:00:00.000000', NULL, 1),
(74568, 2511, 436, '<td valign="top">great detail. wouldn''t a darker shadow be striking!</td>', 'great detail. wouldn''t a darker shadow be striking!', '2002-06-17 14:01:00.000000', NULL, 1),
(74569, 2511, 1944, '<td valign="top">A little blury.</td>', 'A little blury.', '2002-06-17 15:28:00.000000', NULL, 1),
(74570, 2511, 1313, '<td valign="top">A little too close up, but not bad.</td>', 'A little too close up, but not bad.', '2002-06-17 19:13:00.000000', NULL, 1),
(74571, 2511, 2109, '<td valign="top">slightly out of focus</td>', 'slightly out of focus', '2002-06-17 19:22:00.000000', NULL, 1),
