(74786, 2529, 772, '<td valign="top">Very nice textures and light diffusion in the background... Is this water?  - jmsetzler</td>', 'Very nice textures and light diffusion in the background... Is this water?  - jmsetzler', '2002-06-19 13:08:00.000000', NULL, 1),
(74787, 2529, 737, '<td valign="top">I really like the creativity here. Very artistic.</td>', 'I really like the creativity here. Very artistic.', '2002-06-20 12:24:00.000000', NULL, 1),
