(74794, 2530, 327, '<td valign="top">SciFi feel to this......cool. Sorry about the scratches they take away from an otherwise neat shot.</td>', 'SciFi feel to this......cool. Sorry about the scratches they take away from an otherwise neat shot.', '2002-06-17 15:30:00.000000', NULL, 1),
(74795, 2530, 1759, '<td valign="top">This one is a bit unusual, but I find the scratched surface very anoying. I also think (just my opinion) that the shadows are not strongly tied to the subject. To me the subject looks more like the slit of light.</td>', 'This one is a bit unusual, but I find the scratched surface very anoying. I also think (just my opinion) that the shadows are not strongly tied to the subject. To me the subject looks more like the slit of light.', '2002-06-17 16:14:00.000000', NULL, 1),
