(74802, 2530, 1882, '<td valign="top">uh, that''s pretty stupid</td>', 'uh, that''s pretty stupid', '2002-06-18 10:41:00.000000', NULL, 1),
(74803, 2530, 1175, '<td valign="top">You''ve gotta be kidding me.   Its a picture of an elevator door.  There are shades of light and dark but no well defined shadows.</td>', 'You''ve gotta be kidding me.   Its a picture of an elevator door.  There are shades of light and dark but no well defined shadows.', '2002-06-18 12:42:00.000000', NULL, 1),
(74804, 2530, 1037, '<td valign="top">This is a very brave photo. I can see what you were attempting, and there''s a lovely effect going on there with those colours, the brushed metal texture, the shaft of light, etc. But I don''t think it quite works.</td>', 'This is a very brave photo. I can see what you were attempting, and there''s a lovely effect going on there with those colours, the brushed metal texture, the shaft of light, etc. But I don''t think it quite works.', '2002-06-18 13:11:00.000000', NULL, 1),
(74805, 2530, 509, '<td valign="top">I wish I knew what this was, but I don''t really see shadows represented here.  Too abstract for me.</td>', 'I wish I knew what this was, but I don''t really see shadows represented here.  Too abstract for me.', '2002-06-18 15:16:00.000000', NULL, 1),
(74806, 2530, 573, '<td valign="top">Sorry, I just can''t see any ''creative use of shadows'' in this photo.</td>', 'Sorry, I just can''t see any ''creative use of shadows'' in this photo.', '2002-06-18 17:08:00.000000', NULL, 1),
(74807, 2530, 1856, '<td valign="top">Shadow?  I have no personal appreciation for photos like this so my input is probably useless.  The scratch detracts from the line of light.  If that''s what you were trying to highlight then the scratch has gotta go (just whip out your buffer),</td>', 'Shadow?  I have no personal appreciation for photos like this so my input is probably useless.  The scratch detracts from the line of light.  If that''s what you were trying to highlight then the scratch has gotta go (just whip out your buffer),', '2002-06-18 20:43:00.000000', NULL, 1),
