(75001, 2539, 2260, '<td valign="top">hi.love the picture.it doesn''t have that much shaddowish character tho<br/>brittyjo</td>', 'hi.love the picture.it doesn''t have that much shaddowish character thobrittyjo', '2002-06-17 15:02:00.000000', NULL, 1),
(75002, 2539, 2261, '<td valign="top">left hand side was far too dark, shame as the right hand side was great</td>', 'left hand side was far too dark, shame as the right hand side was great', '2002-06-17 15:33:00.000000', NULL, 1),
(75003, 2539, 1658, '<td valign="top">interesting, but the lines of the print on the blankets interrupt the lines of the shadows, making it feel too busy.</td>', 'interesting, but the lines of the print on the blankets interrupt the lines of the shadows, making it feel too busy.', '2002-06-17 15:42:00.000000', NULL, 1),
(75004, 2539, 327, '<td valign="top">I love nudes, but  don''t find this attractive to the model and I don''t find it sexy or even pretty. HOWEVER.....this is about _shadows_ and you did catch them very well.</td>', 'I love nudes, but  don''t find this attractive to the model and I don''t find it sexy or even pretty. HOWEVER.....this is about _shadows_ and you did catch them very well.', '2002-06-17 16:13:00.000000', NULL, 1),
(75005, 2539, 1175, '<td valign="top">I love the curves, and straight lines, and leapord print.</td>', 'I love the curves, and straight lines, and leapord print.', '2002-06-17 18:06:00.000000', NULL, 1),
(75006, 2539, 1856, '<td valign="top">interesting...looks like she''s wearing a sock because the shadow from the blinds suddenly ends.  I''m confused as to what her body language is telling...a better pose would have improved the image for me. 6</td>', 'interesting...looks like she''s wearing a sock because the shadow from the blinds suddenly ends.  I''m confused as to what her body language is telling...a better pose would have improved the image for me. 6', '2002-06-17 22:52:00.000000', NULL, 1),
(75007, 2539, 2235, '<td valign="top">B&amp;W format work well. Concept and use of dark patterns make this photo. Good sharpness</td>', 'B&W format work well. Concept and use of dark patterns make this photo. Good sharpness', '2002-06-18 10:45:00.000000', NULL, 1),
(75008, 2539, 1041, '<td valign="top">I wanted to do something with blinds on a body, too, but never got around to it.  I like it, but IMO, a more plain bed cover would''ve highlighted the shadows not just on the female, but also on the bed.  Also, reposition her a little if you try this shot again so that her foot is also ''striped''.</td>', 'I wanted to do something with blinds on a body, too, but never got around to it.  I like it, but IMO, a more plain bed cover would''ve highlighted the shadows not just on the female, but also on the bed.  Also, reposition her a little if you try this shot again so that her foot is also ''striped''.', '2002-06-18 11:47:00.000000', NULL, 1),
(75009, 2539, 573, '<td valign="top">Normally nude is not in my top ten pick because they are seldom done well.  The simple parallel striped shadows in contrast with the zebra/leopard busy black and white background turn this difficult subject into a striking photograph.</td>', 'Normally nude is not in my top ten pick because they are seldom done well.  The simple parallel striped shadows in contrast with the zebra/leopard busy black and white background turn this difficult subject into a striking photograph.', '2002-06-18 14:46:00.000000', NULL, 1),
(75010, 2539, 1569, '<td valign="top">Kudos---this took a lot of--should I or shouldn''t I.Glad you did.</td>', 'Kudos---this took a lot of--should I or shouldn''t I.Glad you did.', '2002-06-18 20:18:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(75011, 2539, 875, '<td valign="top">I like the hidden face and the contrast between the shadow lines and the model''s curves.  The animal-print spread is a bit much for me!</td>', 'I like the hidden face and the contrast between the shadow lines and the model''s curves.  The animal-print spread is a bit much for me!', '2002-06-19 00:49:00.000000', NULL, 1),
(75012, 2539, 1037, '<td valign="top">Her body is beautiful, and the shadows fall over her curves in a very sensual way. But her pose seems really fearful and closed up, and the sheets are distracting. I''d love to see her looking more relaxed and natural.</td>', 'Her body is beautiful, and the shadows fall over her curves in a very sensual way. But her pose seems really fearful and closed up, and the sheets are distracting. I''d love to see her looking more relaxed and natural.', '2002-06-19 14:26:00.000000', NULL, 1),
(75013, 2539, 2312, '<td valign="top">This is a great photograph. I like how the shadows give a "morning sunrise" effect. And the female subject is absolutely stunning.</td>', 'This is a great photograph. I like how the shadows give a "morning sunrise" effect. And the female subject is absolutely stunning.', '2002-06-19 15:51:00.000000', NULL, 1),
(75014, 2539, 772, '<td valign="top">This is a nicely executed photo for sure... I like these shadows and how they highlight your model... There are two things that may improve this photo... First of all, allowing a little or all of her face to appear would be nice..  Secondly, this leapord skin comforter or what ever it is... I''m thinking that it makes this photo quite busy looking...  another very minor and picky detail is that the shadows on yor model die at her foot.. not a big deal but it was just something that I noticed.  I think I may have seen a similar shot on photosig this week... could be the same photographer and model maybe?  I think you have some definite potential with this model... keep up the good work!  I worked to a similar format this week and I hope to do more like it in the future... if you would like to share ideas sometime, let me know!  Great shot... - jmsetzler</td>', 'This is a nicely executed photo for sure... I like these shadows and how they highlight your model... There are two things that may improve this photo... First of all, allowing a little or all of her face to appear would be nice..  Secondly, this leapord skin comforter or what ever it is... I''m thinking that it makes this photo quite busy looking...  another very minor and picky detail is that the shadows on yor model die at her foot.. not a big deal but it was just something that I noticed.  I think I may have seen a similar shot on photosig this week... could be the same photographer and model maybe?  I think you have some definite potential with this model... keep up the good work!  I worked to a similar format this week and I hope to do more like it in the future... if you would like to share ideas sometime, let me know!  Great shot... - jmsetzler', '2002-06-20 17:58:00.000000', NULL, 1),
(75015, 2539, 1031, '<td valign="top">I would have positioned her so the shadows didn''t stop by her right ankle, but ran over the end of her foot.</td>', 'I would have positioned her so the shadows didn''t stop by her right ankle, but ran over the end of her foot.', '2002-06-21 18:09:00.000000', NULL, 1),
(75016, 2539, 2111, '<td valign="top">What a pretty woman. Beautiful curves (9)</td>', 'What a pretty woman. Beautiful curves (9)', '2002-06-22 11:05:00.000000', NULL, 1),
(75017, 2539, 2140, '<td valign="top">give me a bucket!</td>', 'give me a bucket!', '2002-06-22 23:08:00.000000', NULL, 1),
(75018, 2539, 2366, '<td valign="top">This is really beautiful, very nice use of contour and volume!</td>', 'This is really beautiful, very nice use of contour and volume!', '2002-06-23 16:48:00.000000', NULL, 1),
(75019, 2539, 637, '<td valign="top">Quite arty</td>', 'Quite arty', '2002-06-24 00:13:00.000000', NULL, 1),
(75020, 2539, 312, '<td valign="top">very nice shadows, and the blanket adds nicely to the effect. minor gripes include the fact that you cropped out her foot on the edge there, and that the left side starts to go into a soft focus, which i''m not sure i like. if this shot were a little crisper and cropped a little better, it would have been even nicer than it is. good job, overall.</td>', 'very nice shadows, and the blanket adds nicely to the effect. minor gripes include the fact that you cropped out her foot on the edge there, and that the left side starts to go into a soft focus, which i''m not sure i like. if this shot were a little crisper and cropped a little better, it would have been even nicer than it is. good job, overall.', '2002-06-24 00:35:00.000000', NULL, 1),
(75021, 2540, 1175, '<td valign="top">Need sharper focus on the lego.</td>', 'Need sharper focus on the lego.', '2002-06-17 15:36:00.000000', NULL, 1),
(75022, 2540, 2172, '<td valign="top">Very clean image</td>', 'Very clean image', '2002-06-17 15:46:00.000000', NULL, 1),
(75023, 2540, 327, '<td valign="top">Made me laugh, well done. Focus is off the face, but not bad.</td>', 'Made me laugh, well done. Focus is off the face, but not bad.', '2002-06-17 16:25:00.000000', NULL, 1),
(75024, 2540, 772, '<td valign="top">nice shadow... I am curious why you chose to convert this photo to black and white?</td>', 'nice shadow... I am curious why you chose to convert this photo to black and white?', '2002-06-17 16:27:00.000000', NULL, 1),
(75025, 2540, 2225, '<td valign="top">this is a very simple picture. i like the black and white, it makes it look more dramatic.</td>', 'this is a very simple picture. i like the black and white, it makes it look more dramatic.', '2002-06-17 18:14:00.000000', NULL, 1),
(75026, 2540, 1005, '<td valign="top">Pretty good shot.  Try two things:  Move your light source farther back, it will help make your shadows more distinct (clear edges) and if your camera has any zoom, move back and zoom in to your subject, it will increase your overall definition (make everything appear more clearly).<br/>Photo 6 Creativity 5 Shadows 7 total 6</td>', 'Pretty good shot.  Try two things:  Move your light source farther back, it will help make your shadows more distinct (clear edges) and if your camera has any zoom, move back and zoom in to your subject, it will increase your overall definition (make everything appear more clearly).Photo 6 Creativity 5 Shadows 7 total 6', '2002-06-17 19:48:00.000000', NULL, 1),
(75027, 2540, 1759, '<td valign="top">I can''t say exactly why, but I kind of like this one. You did a good job with the composition and lighting. No blown out highlights and good overall exposure. The composition and angle of view work nicely here. I would prefer a bit sharper focus, maybe more post sharpening.</td>', 'I can''t say exactly why, but I kind of like this one. You did a good job with the composition and lighting. No blown out highlights and good overall exposure. The composition and angle of view work nicely here. I would prefer a bit sharper focus, maybe more post sharpening.', '2002-06-17 20:54:00.000000', NULL, 1),
(75028, 2540, 1856, '<td valign="top">Gotta ask...what''s the attraction for taking pictures of lego and other plastic people?  I''ve seen several and though they''re usually technically good (like this picture) the subject matter seems quite lacking to me.  Why''d you choose this subject?</td>', 'Gotta ask...what''s the attraction for taking pictures of lego and other plastic people?  I''ve seen several and though they''re usually technically good (like this picture) the subject matter seems quite lacking to me.  Why''d you choose this subject?', '2002-06-17 23:22:00.000000', NULL, 1),
(75029, 2540, 2094, '<td valign="top">LEGO MAN!!! Sweet, i like it.</td>', 'LEGO MAN!!! Sweet, i like it.', '2002-06-18 06:37:00.000000', NULL, 1),
(75030, 2540, 1054, '<td valign="top">Heheheh :-)</td>', 'Heheheh :-)', '2002-06-18 17:44:00.000000', NULL, 1),
(75031, 2540, 472, '<td valign="top">where his hat/hair? lol</td>', 'where his hat/hair? lol', '2002-06-19 12:28:00.000000', NULL, 1),
(75032, 2540, 2199, '<td valign="top">I''m reconsidering this one.....I had voted too low....and am moving your score higher now. Really a nice composition and use of light, it just didn''t strike me as favorably on first viewing.</td>', 'I''m reconsidering this one.....I had voted too low....and am moving your score higher now. Really a nice composition and use of light, it just didn''t strike me as favorably on first viewing.', '2002-06-19 13:08:00.000000', NULL, 1),
(75033, 2540, 2301, '<td valign="top">nice picture...</td>', 'nice picture...', '2002-06-20 15:21:00.000000', NULL, 1),
(75035, 2540, 641, '<td valign="top">We love legos in our household.  I think this would have been nice in a color version too.</td>', 'We love legos in our household.  I think this would have been nice in a color version too.', '2002-06-21 17:17:00.000000', NULL, 1),
(75036, 2540, 1041, '<td valign="top">Lego is usually so colorful, why did you choose b&amp;w?</td>', 'Lego is usually so colorful, why did you choose b&w?', '2002-06-21 18:29:00.000000', NULL, 1),
(75037, 2540, 2370, '<td valign="top">simple but impressive!</td>', 'simple but impressive!', '2002-06-23 22:51:00.000000', NULL, 1),
(75038, 2540, 1, '<td valign="top">Simple, but effective.  Check your focus, it doesnt seem to be on the lego man.. he''s a bit blurry.</td>', 'Simple, but effective.  Check your focus, it doesnt seem to be on the lego man.. he''s a bit blurry.', '2002-06-23 23:17:00.000000', NULL, 1),
(75039, 2540, 280, '<td valign="top">ouch my lowest score so far!  Wich is strange as I quite liked this shot.<br/><br/>Just to answer a few of your questions:<br/><br/>Why B&amp;W? I used the B&amp;W version of this shot as I felt the red and yellow of the Lego man distracted from the shadow. <br/><br/>Why Lego?  As a kid I loved Lego.<br/><br/>Where is the hat/hair? All my Lego men lost their hair I just preferred them without :)<br/><br/>Focus? I kinda liked the soft focus, but you peeps didnt so Ill keep that in mind next time.<br/></td>', 'ouch my lowest score so far!  Wich is strange as I quite liked this shot.Just to answer a few of your questions:Why B&W? I used the B&W version of this shot as I felt the red and yellow of the Lego man distracted from the shadow. Why Lego?  As a kid I loved Lego.Where is the hat/hair? All my Lego men lost their hair I just preferred them without :)Focus? I kinda liked the soft focus, but you peeps didnt so Ill keep that in mind next time.', '2002-06-24 14:32:00.000000', NULL, 0),
(75040, 2541, 2263, '<td valign="top">Clever...</td>', 'Clever...', '2002-06-17 16:22:00.000000', NULL, 1),
(75041, 2541, 772, '<td valign="top">It''s a shadow alright, but it''s not scoring points for creativity...</td>', 'It''s a shadow alright, but it''s not scoring points for creativity...', '2002-06-17 16:33:00.000000', NULL, 1),
(75042, 2541, 1041, '<td valign="top">It''s a shadow, but it doesn''t do very much for me.  What''s the purpose of it?  Why choose the grass vs. another background?</td>', 'It''s a shadow, but it doesn''t do very much for me.  What''s the purpose of it?  Why choose the grass vs. another background?', '2002-06-17 17:48:00.000000', NULL, 1),
(75043, 2541, 1054, '<td valign="top">This shot is not overly compelling to me. The flowers are a distraction and composition would be better in portrait mode.</td>', 'This shot is not overly compelling to me. The flowers are a distraction and composition would be better in portrait mode.', '2002-06-17 18:47:00.000000', NULL, 1),
(75044, 2541, 1759, '<td valign="top">As a viewer this leaves me thinking, what am I do do with this? There is nice grass and a shadow, but no story or subject to speak of.</td>', 'As a viewer this leaves me thinking, what am I do do with this? There is nice grass and a shadow, but no story or subject to speak of.', '2002-06-17 22:24:00.000000', NULL, 1),
(75045, 2541, 1175, '<td valign="top">Are you waving?  You gotta do something more interesting than taking a picture of your own shadow.</td>', 'Are you waving?  You gotta do something more interesting than taking a picture of your own shadow.', '2002-06-18 15:36:00.000000', NULL, 1),
(75046, 2541, 1485, '<td valign="top">DUH!  so not original.</td>', 'DUH!  so not original.', '2002-06-19 10:30:00.000000', NULL, 1),
(75047, 2541, 1856, '<td valign="top">At first, I didn''t appreciate this at all...but I kept coming back to it.  I think it would be a great image if you''re entire shadow was in the picture.  How you''d go about actually photographing your entire shadow is beyond me...tripod and remote maybe?  The weedy grass makes a nice background.</td>', 'At first, I didn''t appreciate this at all...but I kept coming back to it.  I think it would be a great image if you''re entire shadow was in the picture.  How you''d go about actually photographing your entire shadow is beyond me...tripod and remote maybe?  The weedy grass makes a nice background.', '2002-06-19 12:17:00.000000', NULL, 1),
(75048, 2541, 811, '<td valign="top">I know this is nitpicky, but the white flowers bother me.  It looks like to many to pick to get out of your way, but it may have been humorous to pick some and arrange them like facial features.  Of course, I have a weird sense of humor, so you may not want to listen to me!</td>', 'I know this is nitpicky, but the white flowers bother me.  It looks like to many to pick to get out of your way, but it may have been humorous to pick some and arrange them like facial features.  Of course, I have a weird sense of humor, so you may not want to listen to me!', '2002-06-19 16:52:00.000000', NULL, 1),
(75049, 2541, 2125, '<td valign="top">looks like a shadow of Jesus....way cool</td>', 'looks like a shadow of Jesus....way cool', '2002-06-20 13:54:00.000000', NULL, 1),
(75050, 2541, 1, '<td valign="top">Bland subjects make for bland photographs.</td>', 'Bland subjects make for bland photographs.', '2002-06-23 20:02:00.000000', NULL, 1),
(75051, 2543, 1054, '<td valign="top">I think if you had someone sleeping in the hammock the shadows would be more evident.</td>', 'I think if you had someone sleeping in the hammock the shadows would be more evident.', '2002-06-17 02:05:00.000000', NULL, 1),
(75052, 2543, 2094, '<td valign="top">Might be nicer with more highlights on the hammock (more contrasting areas)... Still, pretty nice.</td>', 'Might be nicer with more highlights on the hammock (more contrasting areas)... Still, pretty nice.', '2002-06-17 10:08:00.000000', NULL, 1),
(75053, 2543, 772, '<td valign="top">I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...</td>', 'I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...', '2002-06-17 16:45:00.000000', NULL, 1),
(75054, 2543, 2243, '<td valign="top">ahhhhhhhhh! :-)</td>', 'ahhhhhhhhh! :-)', '2002-06-17 20:08:00.000000', NULL, 1),
(75055, 2543, 1759, '<td valign="top">Well exposed and in focus. A decent picture of a hammock in the shade.</td>', 'Well exposed and in focus. A decent picture of a hammock in the shade.', '2002-06-17 20:41:00.000000', NULL, 1),
(75056, 2543, 1599, '<td valign="top">? ? ?</td>', '? ? ?', '2002-06-18 01:59:00.000000', NULL, 1),
(75057, 2543, 1175, '<td valign="top">makes me wanna sleep.  You have shadows in here but it doesn''t work well.  You have a noisy pattern with the threads of the hammock and then you have a random pattern sort of shadow with hot spots of light.  They all sort of clash.  This pattern might just be too noisy for any sort of shadow pick, unless of course, its casting the shadow itself.</td>', 'makes me wanna sleep.  You have shadows in here but it doesn''t work well.  You have a noisy pattern with the threads of the hammock and then you have a random pattern sort of shadow with hot spots of light.  They all sort of clash.  This pattern might just be too noisy for any sort of shadow pick, unless of course, its casting the shadow itself.', '2002-06-18 21:43:00.000000', NULL, 1),
(75058, 2543, 527, '<td valign="top">The whole thing is in shadow making the hammock the center of focus not the shadow.</td>', 'The whole thing is in shadow making the hammock the center of focus not the shadow.', '2002-06-19 00:56:00.000000', NULL, 1),
(75059, 2543, 1, '<td valign="top">The shadows are exactly standing out very well.  Your chosen subject doesnt absorb shadows correctly.</td>', 'The shadows are exactly standing out very well.  Your chosen subject doesnt absorb shadows correctly.', '2002-06-21 20:18:00.000000', NULL, 1),
(75060, 2545, 1175, '<td valign="top">Abstract.  Cool.</td>', 'Abstract.  Cool.', '2002-06-17 14:48:00.000000', NULL, 1),
(75061, 2545, 1759, '<td valign="top">Interesting shadow. Good job, clearly meets the challenge topic. It would be nice to get some more definition and a bit less washout from the light (how?).</td>', 'Interesting shadow. Good job, clearly meets the challenge topic. It would be nice to get some more definition and a bit less washout from the light (how?).', '2002-06-17 16:08:00.000000', NULL, 1),
(75062, 2545, 1041, '<td valign="top">Not a bad abstract shadow at all.  And the shadow is definitely the subject of the shot.  The bottom right is a little bit to blown out for my liking.</td>', 'Not a bad abstract shadow at all.  And the shadow is definitely the subject of the shot.  The bottom right is a little bit to blown out for my liking.', '2002-06-17 17:56:00.000000', NULL, 1),
(75063, 2545, 441, '<td valign="top">not many entries have managed to make the subject the shadow! good try</td>', 'not many entries have managed to make the subject the shadow! good try', '2002-06-17 18:06:00.000000', NULL, 1),
(75064, 2545, 1005, '<td valign="top">Very artsy, but I don''t really like it that much.  At the bottom, too much light/glare hurts the image, soften your light source or move it back, please.<br/>Photo 4 Creativity 5 Shadows 5 total 5</td>', 'Very artsy, but I don''t really like it that much.  At the bottom, too much light/glare hurts the image, soften your light source or move it back, please.Photo 4 Creativity 5 Shadows 5 total 5', '2002-06-17 19:51:00.000000', NULL, 1),
(75065, 2545, 2199, '<td valign="top">I love the composition, abstract....nice texture -- very nice!</td>', 'I love the composition, abstract....nice texture -- very nice!', '2002-06-17 20:13:00.000000', NULL, 1),
(75066, 2545, 1944, '<td valign="top">Nice design. I like the way the texture caries through and unifies the shadow elements.</td>', 'Nice design. I like the way the texture caries through and unifies the shadow elements.', '2002-06-17 21:35:00.000000', NULL, 1),
(75067, 2545, 1599, '<td valign="top">ok</td>', 'ok', '2002-06-18 01:47:00.000000', NULL, 1),
(75068, 2545, 1446, '<td valign="top">I dont get it at all, but the pattern here is interesting anyway.  I might have prefered it flipped upside down so that the stronger focus was towards the front.  Overall an above average shot IMHO.</td>', 'I dont get it at all, but the pattern here is interesting anyway.  I might have prefered it flipped upside down so that the stronger focus was towards the front.  Overall an above average shot IMHO.', '2002-06-18 09:48:00.000000', NULL, 1),
(75069, 2545, 1054, '<td valign="top">Great capture and lighting, excellent lines.</td>', 'Great capture and lighting, excellent lines.', '2002-06-18 15:47:00.000000', NULL, 1),
(75070, 2545, 1037, '<td valign="top">Beautiful. I don''t really have anything else to add.</td>', 'Beautiful. I don''t really have anything else to add.', '2002-06-20 07:10:00.000000', NULL, 1),
(75071, 2545, 772, '<td valign="top">I like the abstract nature of this photo.. this is definitely an interesting shadow :) - jmsetzler</td>', 'I like the abstract nature of this photo.. this is definitely an interesting shadow :) - jmsetzler', '2002-06-20 13:35:00.000000', NULL, 1),
(75072, 2546, 1005, '<td valign="top">Really nice photo technically.  Shadow is the subject, focus is perfect, but what''s the "interest"?  Example:  Paint one brick at the edge of your shadow black/grey in an attempt to trick the viewer that they are seeing something "extra" that is not really there, or keys shining in the sunshine in the shadow of the spokes.  Get where I''m headed?  Thrill me!  Photo 9 Creativity 4 Shadows 6 total 6</td>', 'Really nice photo technically.  Shadow is the subject, focus is perfect, but what''s the "interest"?  Example:  Paint one brick at the edge of your shadow black/grey in an attempt to trick the viewer that they are seeing something "extra" that is not really there, or keys shining in the sunshine in the shadow of the spokes.  Get where I''m headed?  Thrill me!  Photo 9 Creativity 4 Shadows 6 total 6', '2002-06-17 19:22:00.000000', NULL, 1),
(75073, 2546, 1759, '<td valign="top">A nice clear picture. You might play with camera angles to see if anything of interest pops out.</td>', 'A nice clear picture. You might play with camera angles to see if anything of interest pops out.', '2002-06-17 22:16:00.000000', NULL, 1),
(75074, 2546, 1599, '<td valign="top">Nah</td>', 'Nah', '2002-06-18 01:34:00.000000', NULL, 1),
(75075, 2546, 1054, '<td valign="top">Nicely shot and framed.</td>', 'Nicely shot and framed.', '2002-06-18 18:18:00.000000', NULL, 1),
(75076, 2546, 1944, '<td valign="top">The  highlinght areas seem to be a little overexposed, and since you''ve lost the shadows anyway you might have exposed about one stop less or adjusted in your imaging program.</td>', 'The  highlinght areas seem to be a little overexposed, and since you''ve lost the shadows anyway you might have exposed about one stop less or adjusted in your imaging program.', '2002-06-19 00:41:00.000000', NULL, 1),
(75077, 2546, 772, '<td valign="top">Nice choice of framing on this photo :)  The shadows work well here :) - jmsetzler</td>', 'Nice choice of framing on this photo :)  The shadows work well here :) - jmsetzler', '2002-06-19 17:07:00.000000', NULL, 1),
(75078, 2546, 570, '<td valign="top">mountain bikes are gay</td>', 'mountain bikes are gay', '2002-06-20 16:54:00.000000', NULL, 1),
(75079, 2546, 1, '<td valign="top">An uninteresting subject will produce an uninteresting shot.</td>', 'An uninteresting subject will produce an uninteresting shot.', '2002-06-23 19:22:00.000000', NULL, 1),
(75080, 2547, 1054, '<td valign="top">A little too bright.</td>', 'A little too bright.', '2002-06-17 01:55:00.000000', NULL, 1),
