(75602, 2580, 2011, '<td valign="top">This is just an all around GREAT photo.  Clear, clean, bright and dont forget the shadow!  My only 10 this week! Congrats!</td>', 'This is just an all around GREAT photo.  Clear, clean, bright and dont forget the shadow!  My only 10 this week! Congrats!', '2002-06-17 15:46:00.000000', NULL, 1),
(75603, 2580, 2172, '<td valign="top">Nice action shot!  I think for the "Shadow" theme, I would''ve stuck with just the shadow portion of the shot.</td>', 'Nice action shot!  I think for the "Shadow" theme, I would''ve stuck with just the shadow portion of the shot.', '2002-06-17 16:14:00.000000', NULL, 1),
(75604, 2580, 327, '<td valign="top">Mighty nice shadow there, good action shot. Well done.</td>', 'Mighty nice shadow there, good action shot. Well done.', '2002-06-17 16:14:00.000000', NULL, 1),
(75606, 2580, 1759, '<td valign="top">Wow! A difficult high action shot! I don''t know how high up this guy really is, but the camera angle gives the impression of really flying high. Nice shot!</td>', 'Wow! A difficult high action shot! I don''t know how high up this guy really is, but the camera angle gives the impression of really flying high. Nice shot!', '2002-06-17 18:07:00.000000', NULL, 1),
(75607, 2580, 441, '<td valign="top">well caught and worked for</td>', 'well caught and worked for', '2002-06-17 18:12:00.000000', NULL, 1),
(75608, 2580, 2123, '<td valign="top">Perfect balance (so to speak) and color is great too</td>', 'Perfect balance (so to speak) and color is great too', '2002-06-17 19:38:00.000000', NULL, 1),
(75609, 2580, 1313, '<td valign="top">Nice pic, good color, good shadow</td>', 'Nice pic, good color, good shadow', '2002-06-17 19:49:00.000000', NULL, 1),
(75610, 2580, 1599, '<td valign="top">Nice skater. Cool shadow.</td>', 'Nice skater. Cool shadow.', '2002-06-18 02:11:00.000000', NULL, 1),
(75611, 2580, 734, '<td valign="top">such a great image,.... even without the shadow,.. althought the shadow is really cool..great shot.  So did he pull it?</td>', 'such a great image,.... even without the shadow,.. althought the shadow is really cool..great shot.  So did he pull it?', '2002-06-18 03:35:00.000000', NULL, 1),
(75612, 2580, 1, '<td valign="top">Nicely caught and framed.  Maybe try a more dramatic angle (lower to the ground) to give the skater a notion of being very high.</td>', 'Nicely caught and framed.  Maybe try a more dramatic angle (lower to the ground) to give the skater a notion of being very high.', '2002-06-18 09:22:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(75613, 2580, 1882, '<td valign="top">Great action shot!  Cool!</td>', 'Great action shot!  Cool!', '2002-06-18 10:54:00.000000', NULL, 1),
(75614, 2580, 1005, '<td valign="top">Cool action shot.  Very well done.  Don''t change a thing.  Photo 10 Creativity 9 Shadows 9 total 9</td>', 'Cool action shot.  Very well done.  Don''t change a thing.  Photo 10 Creativity 9 Shadows 9 total 9', '2002-06-18 13:49:00.000000', NULL, 1),
(75615, 2580, 1054, '<td valign="top">Good composition, great idea.</td>', 'Good composition, great idea.', '2002-06-18 17:44:00.000000', NULL, 1),
(75616, 2580, 1041, '<td valign="top">Wow, this would''ve done well in stop motion and even people.  Great timing to get the shadow all the way on the half-pipe and the concentration on the guys face.  Love how sharp your shot is.  My top 10 this week.</td>', 'Wow, this would''ve done well in stop motion and even people.  Great timing to get the shadow all the way on the half-pipe and the concentration on the guys face.  Love how sharp your shot is.  My top 10 this week.', '2002-06-18 18:10:00.000000', NULL, 1),
(75617, 2580, 189, '<td valign="top">T''would have been slightly better, inho, if the actual skater were not seen.</td>', 'T''would have been slightly better, inho, if the actual skater were not seen.', '2002-06-18 18:28:00.000000', NULL, 1),
(75618, 2580, 2009, '<td valign="top">Great timing.</td>', 'Great timing.', '2002-06-18 21:35:00.000000', NULL, 1),
(75619, 2580, 1042, '<td valign="top">wonderful stop-action. Nicely done and a great disconnected shadow...good composition. 10 :)</td>', 'wonderful stop-action. Nicely done and a great disconnected shadow...good composition. 10 :)', '2002-06-18 21:43:00.000000', NULL, 1),
(75620, 2580, 554, '<td valign="top">and perfect timing too</td>', 'and perfect timing too', '2002-06-19 00:02:00.000000', NULL, 1),
(75621, 2580, 1793, '<td valign="top">hehe, love the look of concentration on his face.</td>', 'hehe, love the look of concentration on his face.', '2002-06-19 03:07:00.000000', NULL, 1),
(75622, 2580, 2173, '<td valign="top">the emotion are so strong, I love this sport,  I like the picture its so fast<br/><br/>congrats!!</td>', 'the emotion are so strong, I love this sport,  I like the picture its so fastcongrats!!', '2002-06-19 13:08:00.000000', NULL, 1),
(75623, 2580, 2199, '<td valign="top">Excellent. Especially like the use of color...blue sky, red shirt.....and the shadow shape is very unique.</td>', 'Excellent. Especially like the use of color...blue sky, red shirt.....and the shadow shape is very unique.', '2002-06-19 13:13:00.000000', NULL, 1),
(75624, 2580, 2312, '<td valign="top">Nice symmetry with the shadow.</td>', 'Nice symmetry with the shadow.', '2002-06-19 15:25:00.000000', NULL, 1),
(75625, 2580, 772, '<td valign="top">very nice action shot!  great shadow too!  - jmsetzler</td>', 'very nice action shot!  great shadow too!  - jmsetzler', '2002-06-20 17:37:00.000000', NULL, 1),
(75626, 2580, 2346, '<td valign="top">I love action shots, it''s pretty good. I probably would have taken it from a different point of view.</td>', 'I love action shots, it''s pretty good. I probably would have taken it from a different point of view.', '2002-06-21 20:14:00.000000', NULL, 1),
(75627, 2580, 1061, '<td valign="top">Great picture!</td>', 'Great picture!', '2002-06-23 04:46:00.000000', NULL, 1),
(75628, 2580, 661, '<td valign="top">Very nice composition.  Great clarity!</td>', 'Very nice composition.  Great clarity!', '2002-06-24 00:16:00.000000', NULL, 1),
(75629, 2580, 117, '<td valign="top">thanks for your comments and voting</td>', 'thanks for your comments and voting', '2002-06-24 18:22:00.000000', NULL, 0),
(75630, 2581, 1054, '<td valign="top">I like the way the light comes through the glass here.</td>', 'I like the way the light comes through the glass here.', '2002-06-17 01:44:00.000000', NULL, 1),
(75631, 2581, 327, '<td valign="top">Cool I did a shot once simular to this....love that light refraction. Must be the angle but the bowl looks distorted....? Fun shot, nice job.</td>', 'Cool I did a shot once simular to this....love that light refraction. Must be the angle but the bowl looks distorted....? Fun shot, nice job.', '2002-06-17 16:16:00.000000', NULL, 1),
(75632, 2581, 1944, '<td valign="top">I like the concept very much. Would have rated it higher if the plate at the right had been in focus. This could have been a very powerful photo.</td>', 'I like the concept very much. Would have rated it higher if the plate at the right had been in focus. This could have been a very powerful photo.', '2002-06-17 17:30:00.000000', NULL, 1),
(75633, 2581, 1599, '<td valign="top">ok</td>', 'ok', '2002-06-18 01:55:00.000000', NULL, 1),
(75634, 2581, 2221, '<td valign="top">somehow a bit "uneasy".  maybe because there are three objects in focus plus the strong light in the middle. all distributed over the whole picture. addittionally a lot of lines cut the picture. the folds of the cloth and the edge of the shadow from left to right.</td>', 'somehow a bit "uneasy".  maybe because there are three objects in focus plus the strong light in the middle. all distributed over the whole picture. addittionally a lot of lines cut the picture. the folds of the cloth and the edge of the shadow from left to right.', '2002-06-19 10:03:00.000000', NULL, 1),
(75635, 2581, 772, '<td valign="top">The shadow and refractions from the glass of water is nice... I just think that this photo is a little busy... :) - jmsetzler</td>', 'The shadow and refractions from the glass of water is nice... I just think that this photo is a little busy... :) - jmsetzler', '2002-06-20 17:24:00.000000', NULL, 1),
(75636, 2581, 1, '<td valign="top">Two cups and a salt shaker don''t relaly portray dining...  There''s a lot of distractions here too -- maybe the shadows are over done.</td>', 'Two cups and a salt shaker don''t relaly portray dining...  There''s a lot of distractions here too -- maybe the shadows are over done.', '2002-06-23 19:07:00.000000', NULL, 1),
(75637, 2582, 1054, '<td valign="top">Nice framing. Doesn''t affect my score but I don''t understand the title.  EDITED COMMENT: I finally got it... absolutely BRILLIANT!!!!!!!!!</td>', 'Nice framing. Doesn''t affect my score but I don''t understand the title.  EDITED COMMENT: I finally got it... absolutely BRILLIANT!!!!!!!!!', '2002-06-17 01:22:00.000000', NULL, 1),
(75638, 2582, 1221, '<td valign="top">Clever title...the "8" pops right out as the subject!  Nice clarity and crop.  One of the best submitted in this challenge.</td>', 'Clever title...the "8" pops right out as the subject!  Nice clarity and crop.  One of the best submitted in this challenge.', '2002-06-17 02:27:00.000000', NULL, 1),
(75639, 2582, 2000, '<td valign="top">Very creative title, and a good pic to match.</td>', 'Very creative title, and a good pic to match.', '2002-06-17 13:47:00.000000', NULL, 1),
(75640, 2582, 441, '<td valign="top">good strong shadows</td>', 'good strong shadows', '2002-06-17 18:33:00.000000', NULL, 1),
(75641, 2582, 1005, '<td valign="top">Mathmatics, you aren''t going to win, but a very clever title.  (I hope everybody understands your play on words)  Technically great, title makes you think, which is a good thing, but overall the photo still lacks interest (in other words, a reason to want to go back an view this photo more than once)<br/>Photo 9 Creativity 7 Shadows 8 total 8</td>', 'Mathmatics, you aren''t going to win, but a very clever title.  (I hope everybody understands your play on words)  Technically great, title makes you think, which is a good thing, but overall the photo still lacks interest (in other words, a reason to want to go back an view this photo more than once)Photo 9 Creativity 7 Shadows 8 total 8', '2002-06-17 20:05:00.000000', NULL, 1),
(75642, 2582, 2199, '<td valign="top">Very nice composition.....</td>', 'Very nice composition.....', '2002-06-17 20:06:00.000000', NULL, 1),
(75643, 2582, 1599, '<td valign="top">ok</td>', 'ok', '2002-06-18 02:33:00.000000', NULL, 1),
(75644, 2582, 2123, '<td valign="top">I''m a sucker for a bike picture. :-)  I love the "8" that the tire shadows makes...that''s where the eye goes</td>', 'I''m a sucker for a bike picture. :-)  I love the "8" that the tire shadows makes...that''s where the eye goes', '2002-06-18 14:32:00.000000', NULL, 1),
(75645, 2582, 772, '<td valign="top">Interesting shadow :)   I don''t have much to say about this shot... I''m not particularly inspired by the subject, but I think you did a great job with this particular subject :) - jmsetzler</td>', 'Interesting shadow :)   I don''t have much to say about this shot... I''m not particularly inspired by the subject, but I think you did a great job with this particular subject :) - jmsetzler', '2002-06-20 13:37:00.000000', NULL, 1),
(75646, 2582, 1042, '<td valign="top">8...very  clever title. :) I like that.</td>', '8...very  clever title. :) I like that.', '2002-06-23 22:46:00.000000', NULL, 1),
(75647, 2582, 661, '<td valign="top">Like the figure eight.</td>', 'Like the figure eight.', '2002-06-24 00:00:00.000000', NULL, 1),
(75648, 2583, 2251, '<td valign="top">not very big coconuts on your girlfriend<br/></td>', 'not very big coconuts on your girlfriend', '2002-06-17 04:35:00.000000', NULL, 1),
(75649, 2583, 1944, '<td valign="top">Exposure could be better.</td>', 'Exposure could be better.', '2002-06-17 14:15:00.000000', NULL, 1),
(75650, 2583, 1877, '<td valign="top">Cute dog!</td>', 'Cute dog!', '2002-06-17 15:28:00.000000', NULL, 1),
(75651, 2583, 772, '<td valign="top">I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...</td>', 'I see the shadows in this photo, yet they are not adding anything interesting or special to the overall impact of the image...  With ''shadows'' being the subject of this challenge, I feel that the shadows should be playing some definite role in the image...', '2002-06-17 16:40:00.000000', NULL, 1),
(75652, 2583, 1041, '<td valign="top">Steve, your outtakes really do give away your contest submission - this is supposed to be anonymous!  As for the shot, I think it''s much more about the people and the dog rather than the shadows, even though there are shadows in the photo.  The girls face looks a little washed out, so do the guy''s legs.</td>', 'Steve, your outtakes really do give away your contest submission - this is supposed to be anonymous!  As for the shot, I think it''s much more about the people and the dog rather than the shadows, even though there are shadows in the photo.  The girls face looks a little washed out, so do the guy''s legs.', '2002-06-17 19:01:00.000000', NULL, 1),
(75653, 2583, 203, '<td valign="top">Focus.</td>', 'Focus.', '2002-06-17 19:26:00.000000', NULL, 1),
(75654, 2583, 1313, '<td valign="top">I don''t see any coconuts!?</td>', 'I don''t see any coconuts!?', '2002-06-17 19:45:00.000000', NULL, 1),
(75655, 2583, 1599, '<td valign="top">?</td>', '?', '2002-06-18 02:18:00.000000', NULL, 1),
(75656, 2583, 1759, '<td valign="top">A guy, a girl, and a dog. What is the subject here? One technical suggestion, you might try using some unsharp mask on the final photo to give it more of a crisp in focus look.</td>', 'A guy, a girl, and a dog. What is the subject here? One technical suggestion, you might try using some unsharp mask on the final photo to give it more of a crisp in focus look.', '2002-06-18 02:37:00.000000', NULL, 1),
(75657, 2583, 1175, '<td valign="top">Ok at least you captured some shadows.  You need to do something to make this photo more interesting.  For one, get closer to your subject.  The face of the girl is totally washed out.  There is too much distracting background.</td>', 'Ok at least you captured some shadows.  You need to do something to make this photo more interesting.  For one, get closer to your subject.  The face of the girl is totally washed out.  There is too much distracting background.', '2002-06-18 12:43:00.000000', NULL, 1),
(75658, 2583, 509, '<td valign="top">You''re gonna hear this enough I''m sure, but the file size is way below the limit and it shows.  The compression is too strong for this picture.  It takes away a lot from the detail in the people, and the girl''s face may be overexposed.</td>', 'You''re gonna hear this enough I''m sure, but the file size is way below the limit and it shows.  The compression is too strong for this picture.  It takes away a lot from the detail in the people, and the girl''s face may be overexposed.', '2002-06-18 15:11:00.000000', NULL, 1),
(75659, 2583, 1054, '<td valign="top">I would have liked to see this from a different angle, so you could get a tighter crop on your subjects.  As it is it looks like a picture WITH shadows, not a picture OF shadows.  Oh, and tell Dan and Bethy I said hi. ;-)</td>', 'I would have liked to see this from a different angle, so you could get a tighter crop on your subjects.  As it is it looks like a picture WITH shadows, not a picture OF shadows.  Oh, and tell Dan and Bethy I said hi. ;-)', '2002-06-18 17:58:00.000000', NULL, 1),
(75660, 2583, 573, '<td valign="top">I don''t get the story, the title and the photo do not connect.  As for the photo, the girl''s face and arm appear totaly washed out, if your camera can adjust you might try a EV of -1 or even -2.</td>', 'I don''t get the story, the title and the photo do not connect.  As for the photo, the girl''s face and arm appear totaly washed out, if your camera can adjust you might try a EV of -1 or even -2.', '2002-06-19 12:27:00.000000', NULL, 1),
(75661, 2583, 1882, '<td valign="top">I don''t really understand why you submitted this.  I can''t find anything good to say about it; except, well, nice lawn.</td>', 'I don''t really understand why you submitted this.  I can''t find anything good to say about it; except, well, nice lawn.', '2002-06-19 13:08:00.000000', NULL, 1),
(75662, 2583, 811, '<td valign="top">The guy on the left looks almost exactly like one of my former students. (Nothing to do with the picture, just an observation.)  There seems to be almost too much in the background, but I''m not sure what you could have done without cutting out the shadows.  Maybe a picture of just the dog?</td>', 'The guy on the left looks almost exactly like one of my former students. (Nothing to do with the picture, just an observation.)  There seems to be almost too much in the background, but I''m not sure what you could have done without cutting out the shadows.  Maybe a picture of just the dog?', '2002-06-19 16:57:00.000000', NULL, 1),
(75663, 2583, 1005, '<td valign="top">(Is the dog coconut?)  Most skin tones over exposed, except the really tan face and arms.  I know that''s a girl and she must have a face, but couldn''t prove it with this photo.  Please explain the title after the contest.  Photo 5 Creativity 5 Shadows 6 total 5</td>', '(Is the dog coconut?)  Most skin tones over exposed, except the really tan face and arms.  I know that''s a girl and she must have a face, but couldn''t prove it with this photo.  Please explain the title after the contest.  Photo 5 Creativity 5 Shadows 6 total 5', '2002-06-19 18:45:00.000000', NULL, 1),
(75664, 2583, 2243, '<td valign="top">Basically a blurry snapshot.</td>', 'Basically a blurry snapshot.', '2002-06-20 18:16:00.000000', NULL, 1),
(75665, 2583, 2263, '<td valign="top">Good snapshot... :(</td>', 'Good snapshot... :(', '2002-06-20 21:40:00.000000', NULL, 1),
(75666, 2583, 244, '<td valign="top">To me if the challenge is Shadows then a SHADOW is the first thing you should notice.  The first thing I see here is overexposed highligts.  Nice picture of a couple and their dog, not a good picture for this challenge.     Score 2  ------------  Corey</td>', 'To me if the challenge is Shadows then a SHADOW is the first thing you should notice.  The first thing I see here is overexposed highligts.  Nice picture of a couple and their dog, not a good picture for this challenge.     Score 2  ------------  Corey', '2002-06-22 01:29:00.000000', NULL, 1),
(75667, 2583, 1, '<td valign="top">Snapshot?  Aside from that, the shadows aren''t the mains ubject of the photo...</td>', 'Snapshot?  Aside from that, the shadows aren''t the mains ubject of the photo...', '2002-06-23 19:07:00.000000', NULL, 1),
(75668, 2583, 2000, '<td valign="top">If you''re wondering... Coconut is the dog.</td>', 'If you''re wondering... Coconut is the dog.', '2002-06-24 11:02:00.000000', NULL, 0),
(75669, 2584, 1005, '<td valign="top">Good title!  To fit the title to your photo, I think you should have cropped closer to JUST the subject, IMO.   (Is your house number supposed to represent your score/career points type thing?)  Photo 6 (less than "exciting")  Creativity 7 (your title helped here) Shadows 8 total 7</td>', 'Good title!  To fit the title to your photo, I think you should have cropped closer to JUST the subject, IMO.   (Is your house number supposed to represent your score/career points type thing?)  Photo 6 (less than "exciting")  Creativity 7 (your title helped here) Shadows 8 total 7', '2002-06-17 15:48:00.000000', NULL, 1),
(75670, 2584, 2188, '<td valign="top">Makes me wonder what was on the left of the shadow?</td>', 'Makes me wonder what was on the left of the shadow?', '2002-06-17 17:20:00.000000', NULL, 1),
(75671, 2584, 2225, '<td valign="top">your net is broken.</td>', 'your net is broken.', '2002-06-17 18:12:00.000000', NULL, 1),
(75672, 2584, 772, '<td valign="top">Nice shadow :) I would have possibly cropped a little more off the topand bottom to remove the extras :)  Good work!</td>', 'Nice shadow :) I would have possibly cropped a little more off the topand bottom to remove the extras :)  Good work!', '2002-06-17 18:20:00.000000', NULL, 1),
(75673, 2584, 203, '<td valign="top">Trim that string!</td>', 'Trim that string!', '2002-06-17 19:03:00.000000', NULL, 1),
