(75675, 2584, 1856, '<td valign="top">I like the idea of the net shadow...but this would have been better on a different backdrop.</td>', 'I like the idea of the net shadow...but this would have been better on a different backdrop.', '2002-06-17 23:43:00.000000', NULL, 1),
(75676, 2584, 1599, '<td valign="top">and someones address</td>', 'and someones address', '2002-06-18 01:17:00.000000', NULL, 1),
(75677, 2584, 1054, '<td valign="top">Nice depiction of the theme.</td>', 'Nice depiction of the theme.', '2002-06-18 12:43:00.000000', NULL, 1),
(75678, 2584, 1793, '<td valign="top">i''d frame lower to avoid the clutter at the top - i just feel this should be more heavy at the bottom.</td>', 'i''d frame lower to avoid the clutter at the top - i just feel this should be more heavy at the bottom.', '2002-06-19 03:08:00.000000', NULL, 1),
(75679, 2584, 693, '<td valign="top">I think the actual net should have been composed within this photo to give it depth and show separation.</td>', 'I think the actual net should have been composed within this photo to give it depth and show separation.', '2002-06-19 12:36:00.000000', NULL, 1),
(75680, 2584, 1041, '<td valign="top">Nice combination of shade, and the numbers, which seem to have almost the same color.  Need to level your horizons though.</td>', 'Nice combination of shade, and the numbers, which seem to have almost the same color.  Need to level your horizons though.', '2002-06-19 15:05:00.000000', NULL, 1),
(75681, 2584, 2312, '<td valign="top">I like the one hanging thread.</td>', 'I like the one hanging thread.', '2002-06-19 15:37:00.000000', NULL, 1),
(75682, 2584, 641, '<td valign="top">I would trim about an inch or so off the top if it wre me. Otherwise I like it</td>', 'I would trim about an inch or so off the top if it wre me. Otherwise I like it', '2002-06-21 17:02:00.000000', NULL, 1),
(75683, 2584, 2111, '<td valign="top">You did an awesome job. The shadow seems to actually "match" the background. (8)</td>', 'You did an awesome job. The shadow seems to actually "match" the background. (8)', '2002-06-22 11:06:00.000000', NULL, 1),
(75684, 2584, 1, '<td valign="top">Almost perfect framing, I dislike the top part.  Wish you could''ve waited and gotten a better angle with the light (ie- more net).</td>', 'Almost perfect framing, I dislike the top part.  Wish you could''ve waited and gotten a better angle with the light (ie- more net).', '2002-06-22 18:25:00.000000', NULL, 1),
(75685, 2584, 637, '<td valign="top">Would like it better w/o the house number</td>', 'Would like it better w/o the house number', '2002-06-23 02:14:00.000000', NULL, 1),
(75686, 2584, 1061, '<td valign="top">Hey, you''re using my web identity!  Stop that!</td>', 'Hey, you''re using my web identity!  Stop that!', '2002-06-23 04:45:00.000000', NULL, 1),
(75687, 2584, 2123, '<td valign="top">Thanks for all your comments.  This was my first submission and it was a lot of fun.  I actually did try cropping the top and bottom and just the top, but ended up liking it better this way.   And I like the dangling string!! ;-)  I should have leveled my horizon and should have tried to wait for a better angle of the sun - but I took this Saturday evening...lol.</td>', 'Thanks for all your comments.  This was my first submission and it was a lot of fun.  I actually did try cropping the top and bottom and just the top, but ended up liking it better this way.   And I like the dangling string!! ;-)  I should have leveled my horizon and should have tried to wait for a better angle of the sun - but I took this Saturday evening...lol.', '2002-06-24 16:11:00.000000', NULL, 0),
(75688, 2585, 1054, '<td valign="top">I had a heck of a time staying out of my own shot... your idea is an effective alternative.  I wish you were totally in frame here, and the parking stripe at the upper right is a distraction.</td>', 'I had a heck of a time staying out of my own shot... your idea is an effective alternative.  I wish you were totally in frame here, and the parking stripe at the upper right is a distraction.', '2002-06-17 02:12:00.000000', NULL, 1),
