(75728, 2587, 2199, '<td valign="top">I like this image.....I would like it more if the high ceiling were not in the photo, but you have no control over that. Good idea.</td>', 'I like this image.....I would like it more if the high ceiling were not in the photo, but you have no control over that. Good idea.', '2002-06-19 13:46:00.000000', NULL, 1),
(75729, 2587, 2312, '<td valign="top">Great stark lighting makes great shadows!</td>', 'Great stark lighting makes great shadows!', '2002-06-19 15:45:00.000000', NULL, 1),
(75730, 2587, 1658, '<td valign="top">This shot is very well done.  I like that on one level, it almost conveys a sense of quiet stillness, but then also gives this sense of motions in the lines.</td>', 'This shot is very well done.  I like that on one level, it almost conveys a sense of quiet stillness, but then also gives this sense of motions in the lines.', '2002-06-20 12:16:00.000000', NULL, 1),
(75731, 2587, 772, '<td valign="top">I am a sucker for nice patterns and I have seen some good ones in this challenge... yours works very well for me also and the black and white was a nice choice on this photo... great shot! = 8 - jmsetzler</td>', 'I am a sucker for nice patterns and I have seen some good ones in this challenge... yours works very well for me also and the black and white was a nice choice on this photo... great shot! = 8 - jmsetzler', '2002-06-20 18:29:00.000000', NULL, 1),
(75732, 2587, 1, '<td valign="top">Nicely shot.  Wondering if you could''ve gotten the bridge out of the frame.</td>', 'Nicely shot.  Wondering if you could''ve gotten the bridge out of the frame.', '2002-06-22 12:27:00.000000', NULL, 1),
(75733, 2587, 2079, '<td valign="top">Wow, A natural shot with an interesting design. Shooting into the sun adds some difficulty to the shot as well - Nice job -</td>', 'Wow, A natural shot with an interesting design. Shooting into the sun adds some difficulty to the shot as well - Nice job -', '2002-06-23 01:45:00.000000', NULL, 1),
(75734, 2587, 312, '<td valign="top">great shot. wish the overpass wasn''t there, but some things are out of our control. great lines and shadows.</td>', 'great shot. wish the overpass wasn''t there, but some things are out of our control. great lines and shadows.', '2002-06-24 00:01:00.000000', NULL, 1),
(75735, 2587, 637, '<td valign="top">Would like more definition of the sky.</td>', 'Would like more definition of the sky.', '2002-06-24 00:06:00.000000', NULL, 1),
(75736, 2587, 689, '<td valign="top">Just to answer a few of the comments on this. First of all, the highway totally covers the arches. You can notice this if you see where the outside support is for the road. I could have achieved getting it out of the photo, but I would have had no shadows. Second, there was no definition to the sky. This is Dallas. Smog. What more can I say? Third, yes, the poles are out of focus. I goofed! Personally, I liked this shot from the other side, but seeing a Hooters in the background stole from it. I''ll post a link to it as soon as I have a chance to upload it.</td>', 'Just to answer a few of the comments on this. First of all, the highway totally covers the arches. You can notice this if you see where the outside support is for the road. I could have achieved getting it out of the photo, but I would have had no shadows. Second, there was no definition to the sky. This is Dallas. Smog. What more can I say? Third, yes, the poles are out of focus. I goofed! Personally, I liked this shot from the other side, but seeing a Hooters in the background stole from it. I''ll post a link to it as soon as I have a chance to upload it.', '2002-06-24 10:18:00.000000', NULL, 0),
